const rtdal001286Source0001 = "case_match <- function(.x, ..., .default = NULL, .ptype = NULL) {\n  lifecycle::deprecate_soft(\n    when = \"1.2.0\",\n    what = \"case_match()\",\n    with = \"recode_values()\",\n    id = \"dplyr-case-match\"\n  )\n\n  # Matching historical behavior of `case_match()`, which was to work like\n  # `case_when()` and not allow empty `...`. Newer `replace_when()` and\n  # `replace_values()` are a no-op for this case, but we deprecated\n  # `case_match()` at that time so it never moved to the new behavior.\n  allow_empty_dots <- FALSE\n\n  args <- eval_formulas(\n    ...,\n    allow_empty_dots = allow_empty_dots\n  )\n  haystacks <- args$lhs\n  values <- args$rhs\n\n  vec_case_match(\n    needles = .x,\n    haystacks = haystacks,\n    values = values,\n    needles_arg = \".x\",\n    haystacks_arg = \"\",\n    values_arg = \"\",\n    default = .default,\n    default_arg = \".default\",\n    ptype = .ptype,\n    call = current_env()\n  )\n}"

const rtdal001286Source0002 = `vec_case_match <- function(
  needles,
  haystacks,
  values,
  ...,
  needles_arg = "needles",
  haystacks_arg = "haystacks",
  values_arg = "values",
  default = NULL,
  default_arg = "default",
  ptype = NULL,
  call = current_env()
) {
  check_dots_empty0(...)

  obj_check_vector(needles, arg = needles_arg, call = call)
  obj_check_list(haystacks, arg = haystacks_arg, call = call)
  list_check_all_vectors(haystacks, arg = haystacks_arg, call = call)

  haystacks <- vec_cast_common(
    !!!haystacks,
    .to = needles,
    .arg = haystacks_arg,
    .call = call
  )

  conditions <- map(haystacks, vec_in, needles = needles)

  size <- vec_size(needles)

  vec_case_when(
    conditions = conditions,
    values = values,
    default = default,
    ptype = ptype,
    size = size,
    conditions_arg = "",
    values_arg = values_arg,
    default_arg = default_arg,
    error_call = call
  )
}`

