const rtdal001291Source0005 = "all_exprs <- function(..., .vectorised = TRUE) {\n  op <- if (.vectorised) quote(`&`) else quote(`&&`)\n  quo_reduce(..., .op = op)\n}"

const rtdal001291Source0006 = "any_exprs <- function(..., .vectorised = TRUE) {\n  op <- if (.vectorised) quote(`|`) else quote(`||`)\n  quo_reduce(..., .op = op)\n}"

const rtdal001291Source0007 = `quo_reduce <- function(..., .op) {
  stopifnot(is_symbol(.op) || is_function(.op))

  dots <- enquos(...)
  if (length(dots) == 1) {
    return(dots[[1]])
  }

  op_quo <- as_quosure(.op, base_env())
  op <- quo_get_expr(op_quo)

  expr <- reduce(dots, function(x, y) expr((!!op)((!!x), (!!y))))
  new_quosure(expr, quo_get_env(op_quo))
}`

