const rtdal001294Source0016 = "check_grouped <- function(tbl, verb, suffix, alt = FALSE) {\n  if (is_grouped_df(tbl)) {\n    if (alt) {\n      alt_line <- sprintf(\n        \"Use `%s_at(df, vars(-group_cols()), myoperation)` to silence the message.\",\n        verb\n      )\n    } else {\n      alt_line <- chr()\n    }\n    inform(c(\n      sprintf(\n        \"`%s_%s()` ignored the following grouping variables:\",\n        verb,\n        suffix\n      ),\n      set_names(fmt_cols(group_vars(tbl)), \"*\"),\n      \"i\" = alt_line\n    ))\n  }\n}"

const rtdal001294Source0017 = "check_dot_cols <- function(vars, cols) {\n  if (is_null(cols)) {\n    vars\n  } else {\n    inform(\"`.cols` has been renamed and is deprecated, please use `.vars`\")\n    if (missing(vars)) cols else vars\n  }\n}"

const rtdal001294Source0018 = `manip_apply_syms <- function(funs, syms, tbl) {
  out <- vector("list", length(syms) * length(funs))
  dim(out) <- c(length(syms), length(funs))
  syms_position <- match(as.character(syms), tbl_vars(tbl))

  for (i in seq_along(syms)) {
    pos <- syms_position[i]
    for (j in seq_along(funs)) {
      fun <- funs[[j]]
      if (is_quosure(fun)) {
        out[[i, j]] <- expr_substitute(funs[[j]], quote(.), syms[[i]])
      } else {
        out[[i, j]] <- call2(funs[[j]], syms[[i]])
      }
      attr(out[[i, j]], "position") <- pos
    }
  }

  dim(out) <- NULL

  # Use symbols as default names
  unnamed <- !have_name(syms)
  names(syms)[unnamed] <- map_chr(syms[unnamed], as_string)

  if (length(funs) == 1 && !attr(funs, "have_name")) {
    names(out) <- names(syms)
  } else {
    nms <- names(funs) %||% rep("<fn>", length(funs))
    is_fun <- nms == "<fn>" | nms == ""
    nms[is_fun] <- paste0("fn", seq_len(sum(is_fun)))

    nms <- unique_names(nms, quiet = TRUE)
    names(funs) <- nms

    if (length(syms) == 1 && all(unnamed)) {
      names(out) <- names(funs)
    } else {
      syms_names <- ifelse(unnamed, map_chr(syms, as_string), names(syms))
      grid <- expand.grid(var = syms_names, call = names(funs))
      names(out) <- paste(grid$var, grid$call, sep = "_")
    }
  }

  out
}`

