const rtdal001298Source0002 = `minimal_names <- function(name, n) {
  if (is.null(name) && missing(n)) {
    abort(error_name_length_required())
  }

  ## TODO: address scenarios where name is not NULL and n != length(name)?
  if (is.null(name)) {
    rep_len("", n)
  } else {
    name %|% ""
  }
}`

const rtdal001298Source0008 = `make_syntactic <- function(name) {
  name[is.na(name)] <- ""
  name[name == ""] <- "."
  name[name == "..."] <- "...."
  name <- sub("^_", "._", name)

  new_name <- make.names(name)

  X_prefix <- grepl("^X", new_name) & !grepl("^X", name)
  new_name[X_prefix] <- sub("^X", "", new_name[X_prefix])

  dot_suffix <- which(new_name == paste0(name, "."))
  new_name[dot_suffix] <- sub("^(.*)[.]$", ".\\1", new_name[dot_suffix])
  ## illegal characters have been replaced with '.' via make.names()
  ## however, we have:
  ##   * declined its addition of 'X' prefixes
  ##   * turned its '.' suffixes to '.' prefixes

  regex <- paste0(
    "^(?<leading_dots>[.]{0,2})",
    "(?<numbers>[0-9]*)",
    "(?<leftovers>[^0-9]?.*$)"
  )

  re <- re_match(new_name, pattern = regex)
  needs_dots <- which(re$numbers != "")
  needs_third_dot <- (re$leftovers[needs_dots] == "")
  re$leading_dots[needs_dots] <- ifelse(needs_third_dot, "...", "..")
  new_name <- paste0(re$leading_dots, re$numbers, re$leftovers)

  new_name
}`

const rtdal001298Source0011 = "describe_repair <- function(orig_name, name) {\n  if (length(orig_name) != length(name)) {\n    abort(c(\n      \"`orig_name` and `name` have different sizes.\",\n      i = glue(\"`orig_name` is of size {length(orig_name)}.\"),\n      i = glue(\"`name`      is of size {length(name)}.\")\n    ))\n  }\n\n  new_names <- name != minimal_names(orig_name)\n  if (any(new_names)) {\n    msg <- bullets(\n      \"New names:\",\n      paste0(\n        tick_if_needed(orig_name[new_names]),\n        \" -> \",\n        tick_if_needed(name[new_names]),\n        .problem = \"\"\n      )\n    )\n    message(msg)\n  }\n}"

const rtdal001298Source0012 = "re_match <- function(text, pattern, perl = TRUE, ...) {\n  if (!is.character(pattern) || length(pattern) != 1L || is.na(pattern)) {\n    abort(c(\n      \"incompatible `pattern`.\",\n      i = \"`pattern` should be a scalar string.\"\n    ))\n  }\n  text <- as.character(text)\n\n  match <- regexpr(pattern, text, perl = perl, ...)\n\n  start <- as.vector(match)\n  length <- attr(match, \"match.length\")\n  end <- start + length - 1L\n\n  matchstr <- substring(text, start, end)\n  matchstr[start == -1] <- NA_character_\n\n  res <- data.frame(\n    stringsAsFactors = FALSE,\n    .text = text,\n    .match = matchstr\n  )\n\n  if (!is.null(attr(match, \"capture.start\"))) {\n    gstart <- attr(match, \"capture.start\")\n    glength <- attr(match, \"capture.length\")\n    gend <- gstart + glength - 1L\n\n    groupstr <- substring(text, gstart, gend)\n    groupstr[gstart == -1] <- NA_character_\n    dim(groupstr) <- dim(gstart)\n\n    res <- cbind(groupstr, res, stringsAsFactors = FALSE)\n  }\n\n  names(res) <- c(attr(match, \"capture.names\"), \".text\", \".match\")\n  res\n}"

const rtdal001298Source0013 = `bullets <- function(header, ..., .problem) {
  problems <- c(...)
  MAX_BULLETS <- 6L
  if (length(problems) >= MAX_BULLETS) {
    n_more <- length(problems) - MAX_BULLETS + 1L
    problems[[MAX_BULLETS]] <- "..."
    length(problems) <- MAX_BULLETS
  }

  paste0(
    header,
    "\n",
    paste0("* ", problems, collapse = "\n")
  )
}`

