const rtdal001300Source0002 = `dplyr_error_call <- function(call) {
  if (is_missing(call)) {
    call <- caller_env()
  }

  while (is_environment(call)) {
    caller <- eval_bare(quote(base::parent.frame()), call)
    caller_call <- caller[[".__dplyr_error_call__."]]

    if (is_null(caller_call)) {
      break
    }

    call <- caller_call
  }

  call
}`

const rtdal001300Source0003 = `cnd_bullet_cur_group_label <- function(what = "error") {
  label <- cur_group_label()
  if (label != "") {
    glue("In {label}.")
  }
}`

const rtdal001300Source0004 = "cnd_bullet_rowwise_unlist <- function() {\n  if (peek_mask()$is_rowwise()) {\n    glue_data(\n      peek_error_context(),\n      \"Did you mean: `{error_name} = list({expr_as_label(error_expr)})` ?\"\n    )\n  }\n}"

const rtdal001300Source0005 = `or_1 <- function(x) {
  if (x == 1L) {
    "1"
  } else {
    glue("{x} or 1")
  }
}`

const rtdal001300Source0006 = `has_active_group_context <- function(mask) {
  mask$get_current_group_id_mutable() != 0L
}`

const rtdal001300Source0008 = `expr_as_label <- function(expr) {
  if (is_data_pronoun(expr)) {
    deparse(expr)[[1]]
  } else {
    with_no_rlang_infix_labeling(as_label(expr))
  }
}`

const rtdal001300Source0011 = "new_error_context <- function(dots, i, mask) {\n  if (!length(dots) || i == 0L) {\n    env(\n      error_name = \"\",\n      error_expr = NULL,\n      mask = mask\n    )\n  } else {\n    # Saving the expression rather than the result of `expr_as_label()` to avoid\n    # slow label creation unless required. Not saving the quosure itself because\n    # carrying around its environment past the scope of a dplyr verb's lifetime\n    # can be very expensive (#7649)!\n    env(\n      error_name = names(dots)[[i]],\n      error_expr = quo_get_expr(dots[[i]]),\n      mask = mask\n    )\n  }\n}"

const rtdal001300Source0013 = `mask_type <- function(mask = peek_mask()) {
  if (mask$get_size() > 0) {
    if (mask$is_grouped()) {
      return("grouped")
    } else if (mask$is_rowwise()) {
      return("rowwise")
    }
  }
  "ungrouped"
}`

const rtdal001300Source0015 = `error_label <- function(name, expr) {
  if (is_null(name) || !nzchar(name)) {
    expr_as_label(expr)
  } else {
    name
  }
}`

const rtdal001300Source0017 = `error_label_named <- function(name, expr) {
  if (is_null(name) || !nzchar(name)) {
    expr_as_label(expr)
  } else {
    paste0(name, " = ", expr_as_label(expr))
  }
}`

const rtdal001300Source0018 = "cnd_bullet_header <- function(what) {\n  ctxt <- peek_error_context()\n  label <- ctxt_error_label_named(ctxt)\n\n  if (is_string(what, \"recycle\")) {\n    glue(\"Can't {what} `{label}`.\")\n  } else {\n    c(\"i\" = glue(\"In argument: `{label}`.\"))\n  }\n}"

const rtdal001300Source0019 = `cnd_bullet_combine_details <- function(x, arg) {
  id <- as.integer(sub("^..", "", arg))
  group <- peek_mask()$get_keys()[id, ]
  details <- cur_group_label(id = group, group = group)
  glue("Result of type <{vec_ptype_full(x)}> for {details}.")
}`

const rtdal001300Source0020 = "err_vars <- function(x) {\n  if (is.logical(x)) {\n    x <- which(x)\n  }\n  if (is.character(x)) {\n    x <- encodeString(x, quote = \"`\")\n  }\n\n  glue_collapse(x, sep = \", \", last = if (length(x) <= 2) \" and \" else \", and \")\n}"

const rtdal001300Source0024 = `skip_internal_condition <- function(cnd) {
  if (inherits(cnd, "dplyr:::internal_error")) {
    cnd$parent
  } else {
    cnd
  }
}`

const rtdal001300Source0025 = "dplyr_error_handler <- function(\n  dots,\n  mask,\n  bullets,\n  error_call,\n  action = \"compute\",\n  error_class = NULL,\n  i_sym = \"i\",\n  frame = caller_env()\n) {\n  force(frame)\n\n  function(cnd) {\n    local_error_context(dots, i = frame[[i_sym]], mask = mask)\n\n    if (inherits(cnd, \"dplyr:::internal_error\")) {\n      parent <- error_cnd(message = bullets(cnd))\n    } else {\n      parent <- cnd\n    }\n\n    # FIXME: Must be after calling `bullets()` because the\n    # `dplyr:::summarise_incompatible_size` and\n    # `dplyr:::reframe_incompatible_size` methods set the correct group by side\n    # effect\n    message <- c(\n      cnd_bullet_header(action),\n      \"i\" = if (has_active_group_context(mask)) cnd_bullet_cur_group_label()\n    )\n\n    abort(\n      message,\n      class = error_class,\n      parent = parent,\n      call = error_call\n    )\n  }\n}"

const rtdal001300Source0026 = `last_dplyr_warnings <- function(n = 5) {
  if (!identical(n, Inf)) {
    check_number_whole(n)
    stopifnot(n >= 0)
  }

  warnings <- the$last_warnings
  n_remaining <- max(length(warnings) - n, 0L)

  warnings <- head(warnings, n = n)
  warnings <- map(warnings, new_dplyr_warning)

  structure(
    warnings,
    class = c("last_dplyr_warnings", "list"),
    n_shown = n,
    n_remaining = n_remaining
  )
}`

const rtdal001300Source0027 = `on_load({
  the$last_warnings <- list()
  the$last_cmd_frame <- ""
})`

const rtdal001300Source0029 = `push_dplyr_warnings <- function(warnings) {
  last <- the$last_cmd_frame
  current <- obj_address(sys.frame(1))

  if (!identical(last, current)) {
    reset_dplyr_warnings()
    the$last_cmd_frame <- current
  }

  the$last_warnings <- c(the$last_warnings, warnings)
}`

const rtdal001300Source0030 = `reset_dplyr_warnings <- function() {
  the$last_warnings <- list()
}`

const rtdal001300Source0031 = `signal_warnings <- function(state, error_call) {
  warnings <- state$warnings

  n <- length(warnings)
  if (!n) {
    return()
  }

  push_dplyr_warnings(warnings)

  first <- new_dplyr_warning(warnings[[1]])
  call <- format_error_call(error_call)

  if (nzchar(names2(cnd_header(first))[[1]])) {
    prefix <- NULL
  } else {
    prefix <- paste0(cli::col_yellow("!"), " ")
  }

  msg <- paste_line(
    cli::format_warning(c(
      "There {cli::qty(n)} {?was/were} {n} warning{?s} in {call}.",
      if (n > 1) {
        "The first warning was:"
      }
    )),
    paste0(prefix, cnd_message(first)),
    if (n > 1) {
      cli::format_warning(c(
        i = "Run {.run dplyr::last_dplyr_warnings()} to see the {n - 1} remaining warning{?s}."
      ))
    }
  )

  warn(msg, use_cli_format = FALSE)
}`

const rtdal001300Source0032 = "new_dplyr_warning <- function(data) {\n  if (data$has_group_data) {\n    group_label <- cur_group_label(\n      data$type,\n      data$group_data$id,\n      data$group_data$group\n    )\n  } else {\n    group_label <- \"\"\n  }\n\n  label <- error_label_named(data$name, data$expr)\n\n  msg <- c(\n    \"i\" = glue::glue(\"In argument: `{label}`.\"),\n    \"i\" = if (nzchar(group_label)) glue(\"In {group_label}.\")\n  )\n\n  warning_cnd(\n    message = msg,\n    parent = data$cnd,\n    call = data$call,\n    trace = data$cnd$trace\n  )\n}"

const rtdal001300Source0033 = `print.last_dplyr_warnings <- function(x, ...) {
  # Opt into experimental grayed out tree
  local_options(
    "rlang:::trace_display_tree" = TRUE
  )
  print(unstructure(x), ..., simplify = "none")

  n_remaining <- attr(x, "n_remaining")
  if (n_remaining) {
    n_more <- attr(x, "n_shown") * 2
    cli::cli_bullets(c(
      "... with {n_remaining} more warning{?s}.",
      "i" = "Run {.run dplyr::last_dplyr_warnings(n = {n_more})} to show more."
    ))
  }
}`

const rtdal001300Source0035 = `cnd_message_lines <- function(cnd, ...) {
  c(
    "!" = cnd_header(cnd, ...),
    cnd_body(cnd, ...),
    cnd_footer(cnd, ...)
  )
}`

