const rtdal001304Source0001 = `count <- function(x, ..., wt = NULL, sort = FALSE, name = NULL) {
  UseMethod("count")
}`

const rtdal001304Source0002 = `count.data.frame <- function(
  x,
  ...,
  wt = NULL,
  sort = FALSE,
  name = NULL,
  .drop = group_by_drop_default(x)
) {
  dplyr_local_error_call()

  if (!missing(...)) {
    out <- group_by(x, ..., .add = TRUE, .drop = .drop)
  } else {
    out <- x
  }

  wt <- compat_wt(enquo(wt))
  out <- tally(out, wt = !!wt, sort = sort, name = name)

  # Ensure grouping is transient
  out <- dplyr_reconstruct(out, x)

  out
}`

const rtdal001304Source0004 = `tally.data.frame <- function(x, wt = NULL, sort = FALSE, name = NULL) {
  name <- check_n_name(name, group_vars(x))

  dplyr_local_error_call()

  wt <- compat_wt(enquo(wt))
  n <- tally_n(x, wt)

  local_options(dplyr.summarise.inform = FALSE)
  out <- summarise(x, !!name := !!n)

  if (sort) {
    arrange(out, desc(!!sym(name)))
  } else {
    out
  }
}`

