const rtdal001325Source0002 = "dplyr_row_slice <- function(data, i, ...) {\n  if (!is.numeric(i) && !is.logical(i)) {\n    abort(\"`i` must be a numeric or logical vector.\")\n  }\n\n  UseMethod(\"dplyr_row_slice\")\n}"

const rtdal001325Source0003 = `dplyr_row_slice.data.frame <- function(data, i, ...) {
  dplyr_reconstruct(vec_slice(data, i), data)
}`

const rtdal001325Source0004 = `dplyr_row_slice.grouped_df <- function(data, i, ..., preserve = FALSE) {
  out <- vec_slice(as.data.frame(data), i)

  # Index into group_indices, then use that to restore the grouping structure
  groups <- group_data(data)
  new_id <- vec_slice(group_indices(data), i)
  new_grps <- vec_group_loc(new_id)

  rows <- rep(list_of(integer()), length.out = nrow(groups))
  rows[new_grps$key] <- new_grps$loc
  groups$.rows <- rows
  if (!preserve && isTRUE(attr(groups, ".drop"))) {
    groups <- group_data_trim(groups)
  }

  new_grouped_df(out, groups)
}`

const rtdal001325Source0005 = `dplyr_row_slice.rowwise_df <- function(data, i, ..., preserve = FALSE) {
  out <- vec_slice(data, i)
  group_data <- vec_slice(group_keys(data), i)
  new_rowwise_df(out, group_data)
}`

const rtdal001325Source0007 = "dplyr_col_modify.data.frame <- function(data, cols) {\n  # Must be implemented from first principles to avoiding edge cases in\n  # [.data.frame and [.tibble (2.1.3 and earlier).\n\n  # Apply tidyverse recycling rules\n  cols <- vec_recycle_common(!!!cols, .size = nrow(data))\n\n  # Transform to list to avoid stripping inner names with `[[<-`\n  out <- as.list(vec_data(data))\n\n  nms <- as_utf8_character(names2(cols))\n  names(out) <- as_utf8_character(names2(out))\n\n  for (i in seq_along(cols)) {\n    nm <- nms[[i]]\n    out[[nm]] <- cols[[i]]\n  }\n\n  # Transform back to data frame before reconstruction\n  row_names <- .row_names_info(data, type = 0L)\n  out <- new_data_frame(out, n = nrow(data), row.names = row_names)\n\n  dplyr_reconstruct(out, data)\n}"

const rtdal001325Source0008 = `dplyr_col_modify.grouped_df <- function(data, cols) {
  out <- dplyr_col_modify(as_tibble(data), cols)

  if (any(names(cols) %in% group_vars(data))) {
    # regroup
    grouped_df(out, group_vars(data), drop = group_by_drop_default(data))
  } else {
    new_grouped_df(out, group_data(data))
  }
}`

