const rtdal001326Source0002 = `group_by.data.frame <- function(
  .data,
  ...,
  .add = FALSE,
  .drop = group_by_drop_default(.data)
) {
  groups <- group_by_prepare(
    .data,
    ...,
    .add = .add,
    error_call = current_env()
  )
  grouped_df(groups$data, groups$group_names, .drop)
}`

const rtdal001326Source0003 = `ungroup <- function(x, ...) {
  UseMethod("ungroup")
}`

const rtdal001326Source0004 = `ungroup.grouped_df <- function(x, ...) {
  if (missing(...)) {
    as_tibble(x)
  } else {
    old_groups <- group_vars(x)
    to_remove <- tidyselect::eval_select(
      expr = expr(c(...)),
      data = x,
      allow_rename = FALSE
    )
    to_remove <- names(to_remove)

    new_groups <- setdiff(old_groups, to_remove)
    group_by(x, !!!syms(new_groups))
  }
}`

const rtdal001326Source0005 = `ungroup.rowwise_df <- function(x, ...) {
  check_dots_empty()
  as_tibble(x)
}`

const rtdal001326Source0006 = `ungroup.data.frame <- function(x, ...) {
  check_dots_empty()
  x
}`

const rtdal001326Source0007 = "group_by_prepare <- function(\n  .data,\n  ...,\n  .add = FALSE,\n  .dots = deprecated(),\n  add = deprecated(),\n  error_call = caller_env()\n) {\n  error_call <- dplyr_error_call(error_call)\n\n  if (!missing(add)) {\n    lifecycle::deprecate_stop(\"1.0.0\", \"group_by(add = )\", \"group_by(.add = )\")\n  }\n  if (!missing(.dots)) {\n    lifecycle::deprecate_stop(\"1.0.0\", \"group_by(.dots = )\")\n  }\n\n  new_groups <- enquos(..., .ignore_empty = \"all\")\n\n  # If any calls, use mutate to add new columns, then group by those\n  computed_columns <- add_computed_columns(\n    .data,\n    new_groups,\n    error_call = error_call\n  )\n\n  out <- computed_columns$data\n  group_names <- computed_columns$added_names\n\n  if (.add) {\n    group_names <- union(group_vars(.data), group_names)\n  }\n\n  unknown <- setdiff(group_names, tbl_vars(out))\n  if (length(unknown) > 0) {\n    bullets <- c(\n      \"Must group by variables found in `.data`.\",\n      x = glue(\"Column `{unknown}` is not found.\")\n    )\n    abort(bullets, call = error_call)\n  }\n\n  list(\n    data = out,\n    groups = syms(group_names),\n    group_names = group_names\n  )\n}"

const rtdal001326Source0012 = `group_by_drop_default.grouped_df <- function(.tbl) {
  tryCatch(
    {
      !identical(attr(group_data(.tbl), ".drop"), FALSE)
    },
    error = function(e) {
      TRUE
    }
  )
}`

