const rtdal001328Source0001 = "as_group_map_function <- function(.f, error_call = caller_env()) {\n  .f <- rlang::as_function(.f)\n  if (length(form <- formals(.f)) < 2 && !\"...\" %in% names(form)) {\n    bullets <- c(\n      \"`.f` must accept at least two arguments.\",\n      i = \"You can use `...` to absorb unused components.\"\n    )\n    abort(bullets, call = error_call)\n  }\n  .f\n}"

const rtdal001328Source0002 = `group_map <- function(.data, .f, ..., .keep = FALSE) {
  lifecycle::signal_stage("experimental", "group_map()")
  UseMethod("group_map")
}`

const rtdal001328Source0003 = `group_map.data.frame <- function(
  .data,
  .f,
  ...,
  .keep = FALSE,
  keep = deprecated()
) {
  if (!missing(keep)) {
    lifecycle::deprecate_stop(
      "1.0.0",
      "group_map(keep = )",
      "group_map(.keep = )"
    )
  }

  .f <- as_group_map_function(.f)

  # call the function on each group
  chunks <- if (is_grouped_df(.data)) {
    group_split(.data, .keep = isTRUE(.keep))
  } else {
    group_split(.data)
  }
  keys <- group_keys(.data)
  group_keys <- map(seq_len(nrow(keys)), function(i) keys[i, , drop = FALSE])

  if (length(chunks)) {
    map2(chunks, group_keys, .f, ...)
  } else {
    # calling .f with .x and .y set to prototypes
    structure(
      list(),
      ptype = .f(attr(chunks, "ptype"), keys[integer(0L), ], ...)
    )
  }
}`

