const rtdal001332Source0005 = "new_grouped_df <- function(x, groups, ..., class = character()) {\n  if (!is.data.frame(x)) {\n    abort(\"`x` must be a data frame.\")\n  }\n  if (!is.data.frame(groups)) {\n    abort(\"`groups` must be a data frame\")\n  }\n  if (tail(names(groups), 1L) != \".rows\") {\n    abort('The last column of `groups` must be called \".rows\".')\n  }\n\n  new_tibble(\n    x,\n    groups = groups,\n    ...,\n    nrow = NROW(x),\n    class = c(class, \"grouped_df\")\n  )\n}"

