const rtdal001338Source0043 = "check_join_by_dots_empty <- function(..., fn, call) {\n  if (dots_n(...) == 0L) {\n    return()\n  }\n\n  fn <- glue::backtick(glue(\"{fn}()\"))\n\n  message <- c(\n    \"`...` must be empty.\",\n    i = glue(\"Non-empty dots were detected inside {fn}.\")\n  )\n\n  abort(message, call = call)\n}"

const rtdal001338Source0044 = `check_missing_arg <- function(
  arg,
  arg_name,
  fn_name,
  error_call,
  ...,
  binary_op = FALSE
) {
  check_dots_empty0(...)

  if (!is_missing(arg)) {
    return(invisible())
  }

  if (!binary_op) {
    fn_name <- glue("{fn_name}()")
  }

  arg_name <- glue::backtick(arg_name)
  fn_name <- glue::backtick(fn_name)

  message <- c(
    glue("Expressions using {fn_name} can't contain missing arguments."),
    x = glue("Argument {arg_name} is missing.")
  )
  abort(message, call = error_call)
}`

