const rtdal001344Source0002 = "lag <- function(x, n = 1L, default = NULL, order_by = NULL, ...) {\n  if (inherits(x, \"ts\")) {\n    abort(\"`x` must be a vector, not a <ts>, do you want `stats::lag()`?\")\n  }\n  check_dots_empty0(...)\n\n  check_number_whole(n)\n  if (n < 0L) {\n    abort(\"`n` must be positive.\")\n  }\n\n  shift(x, n = n, default = default, order_by = order_by)\n}"

const rtdal001344Source0003 = "lead <- function(x, n = 1L, default = NULL, order_by = NULL, ...) {\n  check_dots_empty0(...)\n\n  check_number_whole(n)\n  if (n < 0L) {\n    abort(\"`n` must be positive.\")\n  }\n\n  shift(x, n = -n, default = default, order_by = order_by)\n}"

const rtdal001344Source0004 = `shift <- function(
  x,
  ...,
  n = 1L,
  default = NULL,
  order_by = NULL,
  error_call = caller_env()
) {
  check_dots_empty0(...)

  if (!is.null(order_by)) {
    out <- with_order(
      order_by = order_by,
      fun = shift,
      x = x,
      n = n,
      default = default,
      error_call = error_call
    )
    return(out)
  }

  obj_check_vector(x, call = error_call)

  check_number_whole(n)
  n <- vec_cast(n, integer(), call = error_call)

  if (!is.null(default)) {
    vec_check_size(default, size = 1L, call = error_call)

    default <- vec_cast(
      x = default,
      to = x,
      x_arg = "default",
      to_arg = "x",
      call = error_call
    )
  }

  lag <- n >= 0L
  n <- abs(n)

  size <- vec_size(x)

  if (n > size) {
    n <- size
  }

  if (is.null(default)) {
    shift_slice(x, n, size, lag)
  } else {
    shift_c(x, n, size, lag, default)
  }
}`

const rtdal001344Source0005 = `shift_slice <- function(x, n, size, lag) {
  loc_default <- vec_rep(NA_integer_, n)

  if (lag) {
    loc <- seq2(1L, size - n)
    loc <- vec_c(loc_default, loc)
    vec_slice(x, loc)
  } else {
    loc <- seq2(1L + n, size)
    loc <- vec_c(loc, loc_default)
    vec_slice(x, loc)
  }
}`

const rtdal001344Source0006 = `shift_c <- function(x, n, size, lag, default) {
  default <- vec_rep(default, n)

  if (lag) {
    loc <- seq2(1L, size - n)
    x <- vec_slice(x, loc)
    vec_c(default, x, .ptype = x)
  } else {
    loc <- seq2(1L + n, size)
    x <- vec_slice(x, loc)
    vec_c(x, default, .ptype = x)
  }
}`

