const rtdal001358Source0004 = `eval_formulas_or_from_and_to <- function(
  ...,
  from,
  to,
  allow_empty_dots,
  user_env = caller_env(2),
  error_call = caller_env()
) {
  implementation <- determine_implementation(
    ...,
    from = from,
    to = to,
    error_call = error_call
  )

  switch(
    implementation,
    "dots" = {
      from_as_list_of_vectors <- TRUE
      to_as_list_of_vectors <- TRUE
      from_arg <- ""
      to_arg <- ""

      args <- eval_formulas(
        ...,
        allow_empty_dots = allow_empty_dots,
        user_env = user_env,
        error_call = error_call
      )
      from <- args$lhs
      to <- args$rhs
    },
    "from-to" = {
      from_as_list_of_vectors <- obj_is_list(from)
      to_as_list_of_vectors <- obj_is_list(to)
      from_arg <- "from"
      to_arg <- "to"
    },
    abort("Unreachable", .internal = TRUE)
  )

  list(
    from = from,
    to = to,
    from_as_list_of_vectors = from_as_list_of_vectors,
    to_as_list_of_vectors = to_as_list_of_vectors,
    from_arg = from_arg,
    to_arg = to_arg
  )
}`

const rtdal001358Source0005 = "determine_implementation <- function(..., from, to, error_call) {\n  has_dots <- !missing(...)\n  has_from <- !is.null(from)\n  has_to <- !is.null(to)\n\n  # Supplied `...`\n  if (has_dots) {\n    if (has_from) {\n      cli::cli_abort(\n        \"Can't supply both {.arg from} and {.arg ...}.\",\n        call = error_call\n      )\n    }\n\n    if (has_to) {\n      cli::cli_abort(\n        \"Can't supply both {.arg to} and {.arg ...}.\",\n        call = error_call\n      )\n    }\n\n    return(\"dots\")\n  }\n\n  # Supplied `from` and `to`\n  if (has_from || has_to) {\n    if (!has_from || !has_to) {\n      cli::cli_abort(\n        \"Must supply both {.arg from} and {.arg to}.\",\n        call = error_call\n      )\n    }\n\n    return(\"from-to\")\n  }\n\n  # Supplied nothing. We use `\"dots\"` here which lets `recode_values()` error\n  # and `replace_values()` be a no-op.\n  \"dots\"\n}"

