const rtdal001367Source0001 = `rowwise <- function(data, ...) {
  UseMethod("rowwise")
}`

const rtdal001367Source0002 = `rowwise.data.frame <- function(data, ...) {
  vars <- tidyselect::eval_select(expr(c(...)), data)
  rowwise_df(data, vars)
}`

const rtdal001367Source0003 = "rowwise.grouped_df <- function(data, ...) {\n  if (!missing(...)) {\n    bullets <- c(\n      \"Can't re-group when creating rowwise data.\",\n      i = \"Either first `ungroup()` or call `rowwise()` without arguments.\"\n    )\n    abort(bullets)\n  }\n  rowwise_df(data, group_vars(data))\n}"

const rtdal001367Source0006 = "new_rowwise_df <- function(data, group_data = NULL, ..., class = character()) {\n  nrow <- nrow(data)\n\n  if (!is.null(group_data)) {\n    if (!is_tibble(group_data) || has_name(group_data, \".rows\")) {\n      msg <- \"`group_data` must be a tibble without a `.rows` column.\"\n      abort(msg)\n    }\n\n    group_data <- new_tibble(vec_data(group_data), nrow = nrow) # strip attributes\n  } else {\n    group_data <- new_tibble(list(), nrow = nrow)\n  }\n  group_data$.rows <- new_list_of(as.list(seq_len(nrow)), ptype = integer())\n\n  new_tibble(\n    data,\n    groups = group_data,\n    ...,\n    nrow = nrow,\n    class = c(class, \"rowwise_df\")\n  )\n}"

const rtdal001367Source0009 = `tbl_sum.rowwise_df <- function(x, ...) {
  c(
    NextMethod(),
    "Rowwise" = commas(group_vars(x))
  )
}`

const rtdal001367Source0010 = `as_tibble.rowwise_df <- function(x, ...) {
  new_tibble(vec_data(x), nrow = nrow(x))
}`

const rtdal001367Source0012 = "`[<-.rowwise_df` <- function(x, i, j, ..., value) {\n  out <- NextMethod()\n  group_vars <- intersect(names(out), group_vars(x))\n  rowwise_df(out, group_vars)\n}"

const rtdal001367Source0014 = `rbind.rowwise_df <- function(...) {
  bind_rows(...)
}`

