const rtdal001372Source0013 = `slice_rows <- function(
  data,
  dots,
  by,
  error_call = caller_env(),
  user_env = caller_env(2)
) {
  error_call <- dplyr_error_call(error_call)

  mask <- DataMask$new(data, by, "slice", error_call = error_call)
  on.exit(mask$forget(), add = TRUE)

  chunks <- slice_eval(mask, dots, error_call = error_call, user_env = user_env)
  slice_indices <- slice_combine(
    chunks,
    dots,
    mask = mask,
    error_call = error_call
  )

  vec_c(!!!slice_indices, .ptype = integer())
}`

const rtdal001372Source0015 = `slice_eval <- function(
  mask,
  dots,
  error_call = caller_env(),
  user_env = caller_env(2)
) {
  index <- 0L
  impl <- function(...) {
    n <- ...length()
    out <- vector("list", n)

    for (i in seq_len(n)) {
      index <<- i

      slice_idx <- ...elt(i)

      if (is.matrix(slice_idx) && mat_n_col(slice_idx) == 1) {
        lifecycle::deprecate_warn(
          when = "1.1.0",
          what = I("Slicing with a 1-column matrix"),
          env = error_call,
          user_env = user_env,
          always = TRUE,
          id = "dplyr-slice-one-column-matrix"
        )
        slice_idx <- slice_idx[, 1]
      }

      out[[i]] <- vec_as_subscript(
        slice_idx,
        logical = "error",
        character = "error",
        arg = as_label(dots[[i]]),
        call = NULL # error always chained to slice()
      )
    }

    index <<- 0L
    vec_c(!!!out, .ptype = integer())
  }

  withCallingHandlers(
    mask$eval_all(quo(impl(!!!dots))),
    error = function(cnd) {
      if (inherits(cnd, "vctrs_error_subscript")) {
        action <- "process"
      } else {
        action <- "compute"
      }
      if (index && is_slice_call(error_call)) {
        local_error_context(dots, index, mask = mask)
        header <- cnd_bullet_header(action)
      } else {
        header <- glue("Can't {action} indices.")
      }

      bullets <- c(header, i = cnd_bullet_cur_group_label())
      abort(bullets, call = error_call, parent = cnd)
    }
  )
}`

const rtdal001372Source0016 = `slice_combine <- function(chunks, dots, mask, error_call = caller_env()) {
  rows <- mask$get_rows()
  slice_indices <- new_list(length(rows))

  withCallingHandlers(
    for (group in seq_along(rows)) {
      current_rows <- rows[[group]]

      loc <- num_as_location(
        i = chunks[[group]],
        n = length(current_rows),
        zero = "remove",
        oob = "remove",
        missing = "remove",
        arg = as_label(dots[[group]]),
        call = NULL # error always chained to slice()
      )
      grp_loc <- current_rows[loc]
      grp_loc <- grp_loc[!is.na(grp_loc)]

      slice_indices[[group]] <- grp_loc
    },
    error = function(cnd) {
      mask$set_current_group(group)
      bullets <- c(
        "Can't compute indices.",
        i = cnd_bullet_cur_group_label()
      )
      abort(bullets, call = error_call, parent = cnd)
    }
  )

  slice_indices
}`

const rtdal001372Source0018 = "check_slice_unnamed_n_prop <- function(\n  ...,\n  n,\n  prop,\n  error_call = caller_env()\n) {\n  if (!missing(n) || !missing(prop)) {\n    return(invisible())\n  }\n\n  # Special case to capture e.g. `slice_head(2)`\n  # Capture dots as quosures so that we can label\n  dots <- enquos(...)\n\n  if (length(dots) == 1L && names2(dots)[[1L]] == \"\") {\n    slice_call <- frame_call(frame = error_call)[[1]]\n    slice_call <- as_label(slice_call)\n    bullets <- c(\n      \"`n` must be explicitly named.\",\n      i = glue(\"Did you mean `{slice_call}(n = {as_label(dots[[1]])})`?\")\n    )\n    abort(bullets, call = error_call)\n  }\n\n  invisible()\n}"

const rtdal001372Source0019 = "check_slice_n_prop <- function(n, prop, error_call = caller_env()) {\n  if (missing(n) && missing(prop)) {\n    list(type = \"n\", n = 1L)\n  } else if (!missing(n) && missing(prop)) {\n    n <- check_constant(n, \"n\", error_call = error_call)\n    if (!is_integerish(n, n = 1) || is.na(n)) {\n      abort(\n        glue(\"`n` must be a round number, not {obj_type_friendly(n)}.\"),\n        call = error_call\n      )\n    }\n    list(type = \"n\", n = n)\n  } else if (!missing(prop) && missing(n)) {\n    prop <- check_constant(prop, \"prop\", error_call = error_call)\n    if (!is.numeric(prop) || length(prop) != 1 || is.na(prop)) {\n      abort(\n        glue(\"`prop` must be a number, not {obj_type_friendly(prop)}.\"),\n        call = error_call\n      )\n    }\n    list(type = \"prop\", prop = prop)\n  } else {\n    abort(\"Must supply `n` or `prop`, but not both.\", call = error_call)\n  }\n}"

const rtdal001372Source0021 = `clamp <- function(min, x, max) {
  if (x < min) {
    min
  } else if (x > max) {
    max
  } else {
    x
  }
}`

const rtdal001372Source0022 = `sample_int <- function(n, size, replace = FALSE, wt = NULL) {
  if (size == 0L) {
    integer(0)
  } else {
    sample.int(n, size, prob = wt, replace = replace)
  }
}`

const rtdal001372Source0023 = `slice_rank_idx <- function(
  order_by,
  size,
  with_ties = TRUE,
  direction = c("asc", "desc"),
  na_rm = FALSE,
  call = caller_env()
) {
  direction <- arg_match0(
    arg = direction,
    values = c("asc", "desc"),
    error_call = call
  )
  # puts missing values at the end
  na_value <- if (direction == "asc") "largest" else "smallest"
  ties <- if (with_ties) "min" else "sequential"

  ranks <- vec_rank(
    x = order_by,
    ties = ties,
    direction = direction,
    na_value = na_value
  )

  keep <- ranks <= size
  if (na_rm) {
    keep[!vec_detect_complete(order_by)] <- FALSE
  }

  which <- which(keep)
  which[order(ranks[which])]
}`

