const rtdal001393Source0007 = "test_that(\"across(.unpack =) uses the result of `.names` as `{outer}`\", {\n  fn <- function(x) {\n    tibble(a = x, b = x + 1)\n  }\n\n  df <- tibble(x = 1, y = 2)\n\n  out <- df |>\n    mutate(across(\n      x:y,\n      list(f = fn),\n      .names = \"{.col}.{.fn}\",\n      .unpack = \"{inner}.{outer}\"\n    ))\n\n  expect_named(out, c(\"x\", \"y\", \"a.x.f\", \"b.x.f\", \"a.y.f\", \"b.y.f\"))\n})"

