const rtdal001393Source0047 = "test_that(\"across() allows renaming in `.cols` (#6895)\", {\n  df <- tibble(x = 1, y = 2, z = 3)\n  cols <- set_names(c(\"x\", \"y\"), c(\"a\", \"b\"))\n\n  expect_identical(\n    mutate(df, across(all_of(cols), identity)),\n    mutate(df, a = x, b = y)\n  )\n  expect_identical(\n    mutate(df, (across(all_of(cols), identity))),\n    mutate(df, a = x, b = y)\n  )\n\n  expect_identical(\n    mutate(df, across(all_of(cols), identity, .names = \"{.col}_name\")),\n    mutate(df, a_name = x, b_name = y)\n  )\n  expect_identical(\n    mutate(df, (across(all_of(cols), identity, .names = \"{.col}_name\"))),\n    mutate(df, a_name = x, b_name = y)\n  )\n})"

