const rtdal001395Source0045 = `test_that("legacy - arrange() supports across() and pick() (#4679)", {
  local_options(lifecycle_verbosity = "quiet")
  local_options(dplyr.legacy_locale = TRUE)

  df <- tibble(x = c(1, 3, 2, 1), y = c(4, 3, 2, 1))

  expect_identical(
    df |> arrange(pick(everything())),
    df |> arrange(x, y)
  )
  expect_identical(
    df |> arrange(across(everything(), .fns = desc)),
    df |> arrange(desc(x), desc(y))
  )
  expect_identical(
    df |> arrange(pick(x)),
    df |> arrange(x)
  )
  expect_identical(
    df |> arrange(across(y, .fns = identity)),
    df |> arrange(y)
  )
})`

const rtdal001395Source0046 = `test_that("legacy - arrange() works with across() and pick() cols that return multiple columns (#6490)", {
  local_options(lifecycle_verbosity = "quiet")
  local_options(dplyr.legacy_locale = TRUE)

  df <- tibble(
    a = c(1, 1, 1),
    b = c(2, 2, 2),
    c = c(4, 4, 3),
    d = c(5, 2, 7)
  )

  expect_identical(
    arrange(
      df,
      across(c(a, b), .fns = identity),
      across(c(c, d), .fns = identity)
    ),
    df[c(3, 2, 1), ]
  )
  expect_identical(
    arrange(df, pick(a, b), pick(c, d)),
    df[c(3, 2, 1), ]
  )
})`

const rtdal001395Source0047 = `test_that("legacy - arrange sorts missings in df-cols correctly", {
  local_options(lifecycle_verbosity = "quiet")
  local_options(dplyr.legacy_locale = TRUE)

  col <- tibble(a = c(1, 1, 1), b = c(3, NA, 1))
  df <- tibble(x = col)

  expect_identical(arrange(df, x), df[c(3, 1, 2), ])
  expect_identical(arrange(df, desc(x)), df[c(1, 3, 2), ])
})`

const rtdal001395Source0048 = `test_that("legacy - arrange with duplicates in a df-col uses a stable sort", {
  local_options(lifecycle_verbosity = "quiet")
  local_options(dplyr.legacy_locale = TRUE)

  col <- tibble(a = c(1, 1, 1, 1, 1), b = c(3, NA, 2, 3, NA))
  df <- tibble(x = col, y = 1:5)

  expect_identical(arrange(df, x)$y, c(3L, 1L, 4L, 2L, 5L))
  expect_identical(arrange(df, desc(x))$y, c(1L, 4L, 3L, 2L, 5L))
})`

const rtdal001395Source0049 = `test_that("legacy - arrange with doubly nested df-col doesn't infloop", {
  local_options(lifecycle_verbosity = "quiet")
  local_options(dplyr.legacy_locale = TRUE)

  one <- tibble(a = c(1, 1, 1, 1, 1), b = c(1, 1, 2, 2, 2))
  two <- tibble(a = c(1, 1, 1, 1, 1), b = c(2, 1, 1, 2, 2))
  col <- tibble(one = one, two = two)
  df <- tibble(x = col, y = c(1, 1, 1, 1, 0))

  expect_identical(arrange(df, x, y), df[c(2, 1, 3, 5, 4), ])
})`

