const rtdal001398Source0001 = "test_that(\"computes group data when `by` is set\", {\n  df <- tibble(x = c(1, 1, 2, 2, 1))\n\n  out <- compute_by(by = x, data = df)\n  expect_identical(out$type, \"grouped\")\n  expect_identical(out$names, \"x\")\n\n  expect_identical(\n    out$data,\n    tibble(x = c(1, 2), \".rows\" := list_of(c(1L, 2L, 5L), c(3L, 4L)))\n  )\n})"

const rtdal001398Source0002 = "test_that(\"computes `by` group data in order of appearance\", {\n  df <- tibble(\n    x = c(5, 4, 5, 5),\n    y = c(2, 3, 1, 2)\n  )\n\n  out <- compute_by(by = c(x, y), data = df)\n\n  expect <- tibble(\n    x = c(5, 4, 5),\n    y = c(2, 3, 1),\n    \".rows\" := list_of(c(1L, 4L), 2L, 3L)\n  )\n\n  expect_identical(out$data, expect)\n})"

const rtdal001398Source0003 = "test_that(\"extracts existing data when `by = NULL`\", {\n  df <- data.frame(x = c(1, 1, 2, 2, 1))\n  out <- compute_by(by = NULL, data = df)\n  expect_identical(out$type, \"ungrouped\")\n  expect_identical(out$names, character())\n  # `compute_by()` is always type stable on `$data` and returns a bare tibble\n  expect_identical(out$data, as_tibble(group_data(df)))\n\n  df <- tibble(x = c(1, 1, 2, 2, 1))\n  out <- compute_by(by = NULL, data = df)\n  expect_identical(out$type, \"ungrouped\")\n  expect_identical(out$names, character())\n  expect_identical(out$data, group_data(df))\n\n  gdf <- group_by(df, x)\n  out <- compute_by(by = NULL, data = gdf)\n  expect_identical(out$type, \"grouped\")\n  expect_identical(out$names, \"x\")\n  expect_identical(out$data, group_data(gdf))\n\n  rdf <- rowwise(df)\n  out <- compute_by(by = NULL, data = rdf)\n  expect_identical(out$type, \"rowwise\")\n  expect_identical(out$names, character())\n  expect_identical(out$data, group_data(rdf))\n})"

const rtdal001398Source0004 = `test_that("empty selection results in ungrouped group data", {
  df <- tibble(x = 1)

  out <- compute_by(by = c(), data = df)
  expect_identical(out$type, "ungrouped")
  expect_identical(out$names, character())
  expect_identical(out$data, group_data(df))
})`

const rtdal001398Source0005 = `test_that("throws tidyselect errors", {
  df <- tibble(x = 1)

  expect_snapshot(error = TRUE, {
    compute_by(by = y, data = df)
  })
})`

const rtdal001398Source0006 = "test_that(\"can't set `.by` with a grouped-df\", {\n  df <- tibble(x = 1:5)\n  gdf <- group_by(df, x)\n\n  expect_snapshot(error = TRUE, {\n    compute_by(x, gdf)\n  })\n})"

const rtdal001398Source0007 = "test_that(\"can't set `.by` with a rowwise-df\", {\n  df <- tibble(x = 1:5)\n  rdf <- rowwise(df)\n\n  expect_snapshot(error = TRUE, {\n    compute_by(x, rdf)\n  })\n})"

const rtdal001398Source0008 = `test_that("can tweak the error args", {
  df <- tibble(x = 1:5)
  gdf <- group_by(df, x)

  expect_snapshot(error = TRUE, {
    compute_by(x, gdf, by_arg = "x", data_arg = "dat")
  })
})`

