const rtdal001400Source0001 = `test_that("matches values in order", {
  x <- 1:3
  expect_equal(
    case_when(
      x <= 1 ~ 1,
      x <= 2 ~ 2,
      x <= 3 ~ 3
    ),
    c(1, 2, 3)
  )
})`

const rtdal001400Source0002 = `test_that("unmatched gets missing value", {
  x <- 1:3
  expect_equal(
    case_when(
      x <= 1 ~ 1,
      x <= 2 ~ 2
    ),
    c(1, 2, NA)
  )
})`

const rtdal001400Source0003 = `test_that("missing values can be replaced (#1999)", {
  x <- c(1:3, NA)
  expect_equal(
    case_when(
      x <= 1 ~ 1,
      x <= 2 ~ 2,
      is.na(x) ~ 0
    ),
    c(1, 2, NA, 0)
  )
})`

const rtdal001400Source0004 = `test_that("NA conditions (#2927)", {
  expect_equal(
    case_when(
      c(TRUE, FALSE, NA) ~ 1:3,
      TRUE ~ 4L
    ),
    c(1L, 4L, 4L)
  )
})`

const rtdal001400Source0005 = "test_that(\"any `TRUE` overrides an `NA`\", {\n  x <- c(1, 2, NA, 3)\n  expect <- c(\"one\", \"not_one\", \"missing\", \"not_one\")\n\n  # `TRUE` overriding before the `NA`\n  expect_identical(\n    case_when(\n      is.na(x) ~ \"missing\",\n      x == 1 ~ \"one\",\n      .default = \"not_one\"\n    ),\n    expect\n  )\n\n  # `TRUE` overriding after the `NA`\n  expect_identical(\n    case_when(\n      x == 1 ~ \"one\",\n      is.na(x) ~ \"missing\",\n      .default = \"not_one\"\n    ),\n    expect\n  )\n})"

const rtdal001400Source0006 = `test_that("case_when can be used in anonymous functions (#3422)", {
  res <- tibble(a = 1:3) |>
    mutate(b = (function(x) case_when(x < 2 ~ TRUE, .default = FALSE))(a)) |>
    pull()
  expect_equal(res, c(TRUE, FALSE, FALSE))
})`

const rtdal001400Source0007 = `test_that("case_when() can be used inside mutate()", {
  out <- mtcars[1:4, ] |>
    mutate(
      out = case_when(
        cyl == 4 ~ 1,
        .data[["am"]] == 1 ~ 2,
        .default = 0
      )
    ) |>
    pull()
  expect_identical(out, c(2, 2, 1, 0))
})`

const rtdal001400Source0008 = `test_that("case_when() conditions must be logical (and aren't cast to logical!)", {
  expect_snapshot(error = TRUE, {
    case_when(1 ~ 2)
  })
  # Make sure input numbering is right in the error message!
  expect_snapshot(error = TRUE, {
    case_when(TRUE ~ 2, 3.5 ~ 4)
  })
})`

const rtdal001400Source0009 = `test_that("case_when() accepts logical condition vectors with attributes (#6678)", {
  x <- structure(c(FALSE, TRUE), label = "foo")
  expect_identical(case_when(x ~ 1, .default = 2), c(2, 1))
})`

const rtdal001400Source0010 = `test_that("case_when() does not accept classed logical conditions", {
  # From a vctrs perspective, these aren't "logical condition indices"
  x <- structure(c(FALSE, TRUE), class = "my_logical")
  expect_snapshot(error = TRUE, {
    case_when(x ~ 1)
  })
})`

const rtdal001400Source0011 = `test_that("case_when() logical conditions can't be arrays (#6862)", {
  x <- array(TRUE, dim = c(3, 3))
  y <- c("a", "b", "c")

  expect_snapshot(error = TRUE, {
    case_when(x ~ y)
  })

  # Not even 1D arrays
  x <- array(TRUE, dim = 3)

  expect_snapshot(error = TRUE, {
    case_when(x ~ y)
  })
})`

const rtdal001400Source0012 = `test_that("can pass quosures to case_when()", {
  fs <- local({
    x <- 3:1
    quos(
      x < 2 ~ TRUE,
      TRUE ~ FALSE
    )
  })
  expect_identical(case_when(!!!fs), c(FALSE, FALSE, TRUE))
})`

const rtdal001400Source0013 = `test_that("can pass nested quosures to case_when()", {
  fs <- local({
    foo <- mtcars$cyl[1:4]
    quos(
      !!quo(foo) == 4 ~ 1,
      TRUE ~ 0
    )
  })
  expect_identical(case_when(!!!fs), c(0, 0, 1, 0))
})`

const rtdal001400Source0014 = `test_that("can pass unevaluated formulas to case_when()", {
  x <- 6:8
  fs <- exprs(
    x == 7L ~ TRUE,
    TRUE ~ FALSE
  )
  expect_identical(case_when(!!!fs), c(FALSE, TRUE, FALSE))

  out <- local({
    x <- 7:9
    case_when(!!!fs)
  })
  expect_identical(out, c(TRUE, FALSE, FALSE))
})`

const rtdal001400Source0015 = `test_that("unevaluated formulas can refer to data mask", {
  fs <- exprs(
    cyl == 4 ~ 1,
    am == 1 ~ 2,
    TRUE ~ 0
  )
  out <- mtcars[1:4, ] |> mutate(out = case_when(!!!fs)) |> pull()
  expect_identical(out, c(2, 2, 1, 0))
})`

const rtdal001400Source0016 = `test_that("unevaluated formulas can contain quosures", {
  quo <- local({
    n <- 4
    quo(n)
  })
  fs <- exprs(
    cyl == !!quo ~ 1,
    am == 1 ~ 2,
    TRUE ~ 0
  )
  out <- mtcars[1:4, ] |> mutate(out = case_when(!!!fs)) |> pull()
  expect_identical(out, c(2, 2, 1, 0))
})`

const rtdal001400Source0017 = `test_that("NULL inputs are compacted", {
  x <- 1:3

  bool <- FALSE
  out <- case_when(
    x == 2 ~ TRUE,
    if (bool) x == 3 ~ NA,
    .default = FALSE
  )
  expect_identical(out, c(FALSE, TRUE, FALSE))

  bool <- TRUE
  out <- case_when(
    x == 2 ~ TRUE,
    if (bool) x == 3 ~ NA,
    .default = FALSE
  )
  expect_identical(out, c(FALSE, TRUE, NA))
})`

const rtdal001400Source0018 = "test_that(\"passes through `.default` correctly\", {\n  expect_identical(case_when(FALSE ~ 1, .default = 2), 2)\n  expect_identical(\n    case_when(c(TRUE, FALSE, TRUE, FALSE, TRUE) ~ 1:5, .default = 2),\n    c(1, 2, 3, 2, 5)\n  )\n})"

const rtdal001400Source0019 = "test_that(\"`.default` isn't part of recycling\", {\n  # Because eventually we want to only take the output size from the LHS conditions,\n  # so having `.default` participate in the common size is a step in the wrong\n  # direction\n  expect_snapshot(error = TRUE, {\n    case_when(FALSE ~ 1L, .default = 2:5)\n  })\n})"

const rtdal001400Source0020 = "test_that(\"`.default` is part of common type computation\", {\n  expect_identical(case_when(TRUE ~ 1L, .default = 2), 1)\n\n  expect_snapshot(error = TRUE, {\n    case_when(TRUE ~ 1L, .default = \"x\")\n  })\n})"

const rtdal001400Source0021 = "test_that(\"passes through `.ptype` correctly\", {\n  expect_identical(case_when(TRUE ~ 1, .ptype = integer()), 1L)\n\n  expect_snapshot(error = TRUE, {\n    case_when(TRUE ~ 1, FALSE ~ 1.5, .ptype = integer())\n  })\n  # Error index is right when `NULL` is involved\n  expect_snapshot(error = TRUE, {\n    case_when(TRUE ~ 1, NULL, FALSE ~ 1.5, .ptype = integer())\n  })\n})"

const rtdal001400Source0022 = "test_that(\"passes through `.size` correctly\", {\n  expect_identical(case_when(TRUE ~ 1, .size = 2), c(1, 1))\n\n  expect_snapshot(error = TRUE, {\n    case_when(TRUE ~ 1:2, .size = 3)\n  })\n  # Error index is right when `NULL` is involved\n  expect_snapshot(error = TRUE, {\n    case_when(TRUE ~ 1:3, NULL, TRUE ~ 1:2, .size = 3)\n  })\n})"

const rtdal001400Source0023 = "test_that(\"can't supply `.default` and `.unmatched`\", {\n  # Probably overkill to add `unmatched_arg` just to get `.unmatched` instead\n  # of `unmatched`.\n  expect_snapshot(error = TRUE, {\n    case_when(TRUE ~ 1, .default = 1, .unmatched = \"error\")\n  })\n})"

const rtdal001400Source0024 = "test_that(\"`.unmatched` is validated\", {\n  # Probably overkill to add `unmatched_arg` to `vec_case_when()` just to get\n  # `.unmatched` instead of `unmatched`\n  expect_snapshot(error = TRUE, {\n    case_when(TRUE ~ 1, .unmatched = \"foo\")\n  })\n  expect_snapshot(error = TRUE, {\n    case_when(TRUE ~ 1, .unmatched = 1)\n  })\n})"

const rtdal001400Source0025 = "test_that(\"`.unmatched` treats `FALSE` like an unmatched location\", {\n  expect_snapshot(error = TRUE, {\n    case_when(\n      c(TRUE, FALSE, TRUE) ~ 1,\n      .unmatched = \"error\"\n    )\n  })\n})"

const rtdal001400Source0026 = "test_that(\"`.unmatched` treats `NA` like an unmatched location\", {\n  expect_snapshot(error = TRUE, {\n    case_when(\n      c(TRUE, NA, TRUE) ~ 1,\n      .unmatched = \"error\"\n    )\n  })\n})"

const rtdal001400Source0027 = "test_that(\"`.unmatched` errors pluralize well\", {\n  # One location\n  x <- letters[1:5]\n  expect_snapshot(error = TRUE, {\n    case_when(\n      x == \"a\" ~ 1,\n      x == \"b\" ~ 2,\n      x == \"c\" ~ 3,\n      x == \"e\" ~ 4,\n      .unmatched = \"error\"\n    )\n  })\n\n  # Two locations\n  x <- letters[1:5]\n  expect_snapshot(error = TRUE, {\n    case_when(\n      x == \"a\" ~ 1,\n      x == \"c\" ~ 2,\n      x == \"e\" ~ 3,\n      .unmatched = \"error\"\n    )\n  })\n\n  # Many locations\n  x <- 1:100\n  expect_snapshot(error = TRUE, {\n    case_when(x == 1 ~ \"a\", .unmatched = \"error\")\n  })\n})"

const rtdal001400Source0028 = `test_that("invalid type errors are correct (#6261) (#6206)", {
  expect_snapshot(error = TRUE, {
    case_when(TRUE ~ 1, TRUE ~ "x")
  })
})`

const rtdal001400Source0029 = "test_that(\"`NULL` formula element throws meaningful error (#7794)\", {\n  # \"Must be a vector\" errors\n  expect_snapshot(error = TRUE, {\n    case_when(NULL ~ NULL)\n\n    case_when(TRUE ~ NULL)\n    case_when(NULL ~ TRUE)\n\n    case_when(c(TRUE, TRUE) ~ NULL)\n    case_when(NULL ~ c(TRUE, TRUE))\n\n    case_when(TRUE ~ NULL, c(TRUE, TRUE) ~ NULL)\n    case_when(NULL ~ TRUE, NULL ~ c(TRUE, TRUE))\n  })\n\n  # Recycling errors come first\n  expect_snapshot(error = TRUE, {\n    case_when(c(TRUE, TRUE) ~ NULL, c(TRUE, TRUE, TRUE) ~ NULL)\n    case_when(NULL ~ c(TRUE, TRUE), NULL ~ c(TRUE, TRUE, TRUE))\n  })\n})"

const rtdal001400Source0030 = `test_that("throws chained errors when formula evaluation fails", {
  expect_snapshot(error = TRUE, {
    case_when(1 ~ 2, 3 ~ stop("oh no!"))
  })
  expect_snapshot(error = TRUE, {
    case_when(1 ~ 2, stop("oh no!") ~ 4)
  })
})`

const rtdal001400Source0031 = `test_that("case_when() give meaningful errors", {
  expect_snapshot({
    (expect_error(
      case_when(
        c(TRUE, FALSE) ~ 1:3,
        c(FALSE, TRUE) ~ 1:2
      )
    ))

    (expect_error(
      case_when(
        c(TRUE, FALSE) ~ 1,
        c(FALSE, TRUE, FALSE) ~ 2,
        c(FALSE, TRUE, FALSE, NA) ~ 3
      )
    ))

    (expect_error(
      case_when(51:53 ~ 1:3)
    ))
    (expect_error(
      case_when(paste(50))
    ))
    (expect_error(
      case_when(y ~ x, paste(50))
    ))
    (expect_error(
      case_when()
    ))
    (expect_error(
      case_when(NULL)
    ))
    (expect_error(
      case_when(~ 1:2)
    ))
  })
})`

const rtdal001400Source0032 = "test_that(\"Using scalar LHS with vector RHS is deprecated (#7082)\", {\n  # In many packages, people use `case_when()` when they should be using a\n  # series of if statements. We try to warn when we detect this.\n  expect_snapshot({\n    # Columns\n    x <- 1:5\n    y <- 6:10\n\n    # Scalars\n    code <- 1L\n    sex <- \"M\"\n\n    # This is really a series of if statements.\n    # This is highly inefficient because each scalar LHS is recycled to size 5.\n    expect_identical(\n      case_when(\n        code == 1L && sex == \"M\" ~ x,\n        code == 1L && sex == \"F\" ~ y,\n        code == 1L && sex == \"M\" ~ x + 1L,\n        .default = 0L\n      ),\n      x\n    )\n  })\n\n  # Motivating example of a silent bug that results from allowing this kind of\n  # common size determination (#7082). We ideally want this case to fail. LHS\n  # common size is 1 and RHS inputs ideally should be forced to recycle to this\n  # size. Since both the LHS and RHS inputs are consulted to compute a common\n  # size of 0, this incorrectly returns `character()`, but we at least warn the\n  # user that something is fishy here, and hopefully they take a closer look and\n  # catch their error.\n  expect_snapshot({\n    x <- 1\n    case_when(\n      x == 1 ~ \"a\",\n      x == 2 ~ character(),\n      .default = \"other\"\n    )\n  })\n\n  # Now confirm that the other 3 possible combinations don't warn!\n\n  # size 1 LHS, size 1 RHS\n  expect_identical(\n    expect_no_warning(case_when(TRUE ~ \"a\", FALSE ~ \"b\")),\n    \"a\"\n  )\n  # size >1 LHS, size 1 RHS\n  expect_identical(\n    expect_no_warning(case_when(c(TRUE, FALSE) ~ \"a\", c(FALSE, TRUE) ~ \"b\")),\n    c(\"a\", \"b\")\n  )\n  # size >1 LHS, size >1 RHS\n  expect_identical(\n    expect_no_warning(case_when(\n      c(TRUE, FALSE) ~ c(\"a\", \"b\"),\n      c(FALSE, TRUE) ~ c(\"c\", \"d\")\n    )),\n    c(\"a\", \"d\")\n  )\n})"

const rtdal001400Source0033 = `test_that("replace_when() recycles scalar RHS", {
  x <- c(1, 2, 3, 1, 2, 3)

  expect_identical(
    replace_when(x, x == 1 ~ 0, x == 3 ~ 4),
    c(0, 2, 4, 0, 2, 4)
  )
})`

const rtdal001400Source0034 = "test_that(\"replace_when() allows vector RHS of the same size as `x`\", {\n  x <- c(1, 2, 3, 1, 2, 3)\n  y <- seq_along(x)\n\n  expect_identical(\n    replace_when(x, x == 1 ~ 0, x == 3 ~ y),\n    c(0, 2, 3, 0, 2, 6)\n  )\n\n  expect_snapshot(error = TRUE, {\n    replace_when(x, x == 1 ~ 1:3)\n  })\n})"

const rtdal001400Source0035 = "test_that(\"replace_when() does not recycle LHS values\", {\n  # Unlike `case_when()` we get to do this right!\n  x <- c(1, 2, 3)\n\n  expect_snapshot(error = TRUE, {\n    replace_when(x, TRUE ~ 0)\n  })\n\n  # Error index is right when `NULL` is involved\n  expect_snapshot(error = TRUE, {\n    replace_when(x, c(TRUE, TRUE, TRUE) ~ 0, NULL, TRUE ~ 0)\n  })\n})"

const rtdal001400Source0036 = "test_that(\"replace_when() retains the type of `x`\", {\n  x <- c(1L, 2L)\n\n  # Not going towards common type of double\n  expect_identical(\n    replace_when(x, x == 1L ~ 0),\n    c(0L, 2L)\n  )\n\n  x <- factor(c(\"a\", \"b\", \"c\"))\n\n  # Note common type would be character\n  expect_identical(\n    replace_when(x, x == \"a\" ~ \"c\"),\n    factor(c(\"c\", \"b\", \"c\"), levels = c(\"a\", \"b\", \"c\"))\n  )\n\n  # Can't cast to unknown level\n  expect_snapshot(error = TRUE, {\n    replace_when(x, x == \"a\" ~ \"d\")\n  })\n  # Error index is right when `NULL` is involved\n  expect_snapshot(error = TRUE, {\n    replace_when(x, x == \"a\" ~ \"b\", NULL, x == \"b\" ~ \"d\")\n  })\n})"

const rtdal001400Source0037 = "test_that(\"replace_when() retains names of `x`, consistent with `base::replace()`\", {\n  x <- c(a = 1, b = 2, c = 3)\n\n  expect_identical(\n    replace_when(\n      x,\n      x == 1 ~ 0,\n      x == 3 ~ c(z = 4)\n    ),\n    c(a = 0, b = 2, c = 4)\n  )\n\n  # `x` does not become named if RHS inputs are named\n  x <- c(1, 2, 3)\n\n  expect_identical(\n    replace_when(\n      x,\n      x == 1 ~ c(a = 0),\n      x == 3 ~ c(b = 4)\n    ),\n    c(0, 2, 4)\n  )\n})"

const rtdal001400Source0038 = "test_that(\"replace_when() does not allow named `...`\", {\n  # Purposefully stricter than `case_when()`\n  expect_snapshot(error = TRUE, {\n    replace_when(1, foo = TRUE ~ 2)\n  })\n})"

const rtdal001400Source0039 = "test_that(\"replace_when() compacts `NULL` inputs\", {\n  expect_identical(\n    replace_when(1, NULL, TRUE ~ 2, NULL),\n    2\n  )\n})"

const rtdal001400Source0040 = "test_that(\"replace_when() is a no-op with zero conditions\", {\n  # Unlike `case_when()`, where when zero conditions are supplied\n  # we don't know what kind of vector to build (and we refuse to\n  # build an `unspecified` vector, unlike `vec_case_when()`)\n  expect_identical(replace_when(1), 1)\n  expect_identical(replace_when(1, NULL), 1)\n})"

const rtdal001400Source0041 = `test_that("replace_when() works with data frames", {
  x <- tibble(a = c(1, 2, 3, 1), b = c(2, 3, 4, 2))

  expect_identical(
    replace_when(
      x,
      vec_equal(x, tibble(a = 1, b = 2)) ~ NA
    ),
    vec_assign(x, c(1, 4), NA)
  )

  expect_identical(
    replace_when(
      x,
      vec_equal(x, tibble(a = 1, b = 2)) ~ tibble(a = 0, b = -1)
    ),
    vec_assign(x, c(1, 4), tibble(a = 0, b = -1))
  )
})`

