const rtdal001407Source0001 = `test_that("can use character vectors or bare functions", {
  df <- data.frame(x = 1:3)
  expect_equal(summarise_all(df, "mean"), data.frame(x = 2))
  expect_equal(summarise_all(df, mean), data.frame(x = 2))

  expect_equal(mutate_all(df, list(x = "mean")), data.frame(x = rep(2, 3)))
  expect_equal(mutate_all(df, list(x = mean)), data.frame(x = rep(2, 3)))
})`

const rtdal001407Source0002 = `test_that("default names are smallest unique set", {
  df <- data.frame(x = 1:3, y = 1:3)

  expect_named(summarise_at(df, vars(x:y), list(mean)), c("x", "y"))
  expect_named(
    summarise_at(df, vars(x), list(mean = mean, sd = sd)),
    c("mean", "sd")
  )
  expect_named(
    summarise_at(df, vars(x:y), list(mean = mean, sd = sd)),
    c("x_mean", "y_mean", "x_sd", "y_sd")
  )
})`

const rtdal001407Source0003 = `test_that("named arguments force complete names", {
  df <- data.frame(x = 1:3, y = 1:3)

  expect_named(
    summarise_at(df, vars(x:y), list(mean = mean)),
    c("x_mean", "y_mean")
  )
  expect_named(
    summarise_at(df, vars(x = x), list(mean = mean, sd = sd)),
    c("x_mean", "x_sd")
  )
})`

const rtdal001407Source0005 = `test_that("can select colwise", {
  columns <- iris |> mutate_at(NULL, as.character)
  expect_classes(columns, "nnnnf")

  columns <- iris |> mutate_at(vars(starts_with("Petal")), as.character)
  expect_classes(columns, "nnccf")

  numeric <- iris |> mutate_at(c(1, 3), as.character)
  expect_classes(numeric, "cncnf")

  character <- iris |> mutate_at("Species", as.character)
  expect_classes(character, "nnnnc")
})`

const rtdal001407Source0006 = `test_that("can probe colwise", {
  predicate <- iris |> mutate_if(is.factor, as.character)
  expect_classes(predicate, "nnnnc")

  logical <- iris |> mutate_if(c(TRUE, FALSE, TRUE, TRUE, FALSE), as.character)
  expect_classes(logical, "cnccf")
})`

