const rtdal001407Source0030 = `test_that("rlang lambda inherit from the data mask (#3843)", {
  res <- iris |>
    mutate_at(
      vars(starts_with("Petal")),
      ~ ifelse(Species == "setosa" & . < 1.5, NA, .)
    )
  expected <- iris |>
    mutate(
      Petal.Length = ifelse(
        Species == "setosa" & Petal.Length < 1.5,
        NA,
        Petal.Length
      ),
      Petal.Width = ifelse(
        Species == "setosa" & Petal.Width < 1.5,
        NA,
        Petal.Width
      )
    )
  expect_identical(res, expected)

  res <- iris |>
    group_by(Species) |>
    mutate_at(
      vars(starts_with("Petal")),
      ~ ifelse(Species == "setosa" & . < 1.5, NA, .)
    )
  expected <- iris |>
    group_by(Species) |>
    mutate(
      Petal.Length = ifelse(
        Species == "setosa" & Petal.Length < 1.5,
        NA,
        Petal.Length
      ),
      Petal.Width = ifelse(
        Species == "setosa" & Petal.Width < 1.5,
        NA,
        Petal.Width
      )
    )
  expect_identical(res, expected)
})`

const rtdal001407Source0031 = `test_that("_if isn't tripped up by columns named 'i' (#5330)", {
  test_df <- tibble(i = c("a", "b"), j = c(1, 2))

  result_df <- test_df |>
    mutate_if(is.character, as.factor)

  expect_equal(result_df$i, as.factor(test_df$i))
  expect_equal(result_df$j, test_df$j)
})`

const rtdal001407Source0032 = `test_that("colwise mutate gives meaningful error messages", {
  expect_snapshot({
    # column not found
    (expect_error(
      mutate_at(tibble(), "test", ~1)
    ))

    # not summarising grouping variables
    tbl <- tibble(gr1 = rep(1:2, 4), gr2 = rep(1:2, each = 4), x = 1:8)
    tbl <- group_by(tbl, gr1)
    (expect_error(
      summarise_at(tbl, vars(gr1), mean)
    ))

    # improper additional arguments
    (expect_error(
      mutate_all(mtcars, length, 0, 0)
    ))
    (expect_error(
      mutate_all(mtcars, mean, na.rm = TRUE, na.rm = TRUE)
    ))
  })
})`

