const rtdal001409Source0001 = "test_that(\"tbl_at_vars() treats `NULL` as empty inputs\", {\n  expect_identical(tbl_at_vars(mtcars, vars(NULL)), tbl_at_vars(mtcars, vars()))\n  expect_identical(\n    tibble::remove_rownames(mutate_at(mtcars, vars(NULL), `*`, 100)),\n    tibble::remove_rownames(mtcars)\n  )\n})"

const rtdal001409Source0002 = `test_that("lists of formulas are auto-named", {
  df <- tibble(x = 1:3, y = 4:6)

  out <- df |> summarise_all(list(~ mean(.), ~ sd(.x, na.rm = TRUE)))
  expect_named(out, c("x_mean", "y_mean", "x_sd", "y_sd"))

  out <- df |> summarise_all(list(foobar = ~ mean(.), ~ sd(.x, na.rm = TRUE)))
  expect_named(out, c("x_foobar", "y_foobar", "x_sd", "y_sd"))
})`

const rtdal001409Source0003 = `test_that("colwise utils gives meaningful error messages", {
  expect_snapshot({
    (expect_error(
      tbl_at_vars(iris, raw(3))
    ))
    (expect_error(
      tbl_if_vars(iris, list(identity, force), environment())
    ))

    .funs <- as_fun_list(list(identity, force), caller_env())
    (expect_error(
      tbl_if_vars(iris, .funs, environment())
    ))
  })
})`

