const rtdal001410Source0005 = "test_that(\"warnings are collected for `last_dplyr_warnings()`\", {\n  skip_if_not_installed(\"base\", \"3.6.0\")\n\n  local_options(\n    rlang_trace_format_srcrefs = FALSE\n  )\n\n  df <- tibble(id = 1:2)\n  f <- function() {\n    warning(\"msg\")\n    1\n  }\n\n  reset_dplyr_warnings()\n  expect_snapshot({\n    \"Ungrouped\"\n    df |>\n      mutate(x = f()) |>\n      invisible()\n    last_dplyr_warnings()\n  })\n\n  reset_dplyr_warnings()\n  expect_snapshot({\n    \"Grouped\"\n    df |>\n      group_by(id) |>\n      mutate(x = f()) |>\n      invisible()\n    last_dplyr_warnings()\n  })\n\n  reset_dplyr_warnings()\n  expect_snapshot({\n    \"Rowwise\"\n    df |>\n      rowwise() |>\n      mutate(x = f()) |>\n      invisible()\n    last_dplyr_warnings()\n  })\n\n  reset_dplyr_warnings()\n  expect_snapshot({\n    \"Multiple type of warnings within multiple verbs\"\n    df |>\n      group_by(g = f():n()) |>\n      rowwise() |>\n      mutate(x = f()) |>\n      group_by(id) |>\n      mutate(x = f()) |>\n      invisible()\n    last_dplyr_warnings()\n  })\n\n  reset_dplyr_warnings()\n  expect_snapshot({\n    \"Truncated (1 more)\"\n    df |>\n      rowwise() |>\n      mutate(x = f())\n    last_dplyr_warnings(n = 1)\n  })\n\n  reset_dplyr_warnings()\n  expect_snapshot({\n    \"Truncated (several more)\"\n    df <- tibble(id = 1:5)\n    df |>\n      rowwise() |>\n      mutate(x = f())\n    last_dplyr_warnings(n = 1)\n  })\n})"

const rtdal001410Source0006 = `test_that("complex backtraces with base and rlang warnings", {
  skip_if_not_installed("base", "3.6.0")
  local_options(
    rlang_trace_format_srcrefs = FALSE
  )
  reset_dplyr_warnings()

  df <- tibble(id = 1:3)

  f <- function(...) g(...)
  g <- function(...) h(...)
  h <- function(x, base = TRUE) {
    if (base) {
      warning("foo")
    } else {
      warn("foo")
    }
    x
  }

  foo <- function() bar()
  bar <- function() {
    df |>
      group_by(x = f(1):n()) |>
      mutate(x = f(1, base = FALSE))
  }

  expect_snapshot({
    foo()
    last_dplyr_warnings()
  })
})`

const rtdal001410Source0007 = "test_that(\"`last_dplyr_warnings()` only records 5 backtraces\", {\n  reset_dplyr_warnings()\n\n  f <- function() {\n    warning(\"msg\")\n    1\n  }\n  df <- tibble(id = 1:10)\n\n  expect_warning(\n    df |>\n      group_by(id) |>\n      mutate(x = f())\n  )\n\n  warnings <- last_dplyr_warnings(Inf)\n\n  traces <- map(warnings, `[[`, \"trace\")\n  expect_equal(\n    sum(map_lgl(traces, is_null)),\n    5\n  )\n})"

const rtdal001410Source0008 = `test_that("can collect warnings in main verbs", {
  reset_dplyr_warnings()

  f <- function() {
    warning("foo")
    TRUE
  }

  expect_snapshot({
    invisible(
      mtcars |>
        rowwise() |>
        filter(f()) |>
        arrange(f()) |>
        mutate(a = f()) |>
        summarise(b = f())
    )

    warnings <- last_dplyr_warnings(Inf)
    warnings[[1]] # filter()
    warnings[[33]] # arrange()
    warnings[[65]] # mutate()
    warnings[[97]] # summarise()
  })
})`

