const rtdal001414Source0001 = "test_that(\"count sorts output by keys by default\", {\n  # Due to usage of `summarise()` internally\n  df <- tibble(x = c(2, 1, 1, 2, 1))\n  out <- count(df, x)\n  expect_equal(out, tibble(x = c(1, 2), n = c(3, 2)))\n})"

