const rtdal001419Source0001 = `test_that("cur_data() is deprecated", {
  df <- tibble(x = 1)
  expect_snapshot(mutate(df, y = cur_data()))
})`

const rtdal001419Source0002 = `test_that("cur_data_all() is deprecated", {
  df <- tibble(x = 1)
  expect_snapshot(mutate(df, y = cur_data_all()))
})`

const rtdal001419Source0003 = `test_that("cur_data() gives current data without groups, cur_data_all() includes groups", {
  options(lifecycle_verbosity = "quiet")

  df <- tibble(x = c("b", "a", "b"), y = 1:3)
  gf <- group_by(df, x)

  expect_equal(
    df |> summarise(x = list(cur_data())) |> pull(),
    list(df)
  )

  expect_equal(
    gf |> summarise(x = list(cur_data())) |> pull(),
    list(tibble(y = 2L), tibble(y = c(1L, 3L)))
  )
  expect_equal(
    gf |> summarise(x = list(cur_data_all())) |> pull(),
    list(tibble(x = "a", y = 2L), tibble(x = "b", y = c(1L, 3L)))
  )
})`

const rtdal001419Source0004 = `test_that("cur_data()/cur_data_all() keeps list columns as lists in rowwise_df (#5901)", {
  options(lifecycle_verbosity = "quiet")

  df <- tibble(x = list(tibble(a = 1), tibble(a = 2))) |>
    rowwise()

  expect_true(
    all(summarise(df, test = obj_is_list(cur_data()$x))$test)
  )
  expect_true(
    all(summarise(df, test = obj_is_list(cur_data_all()$x))$test)
  )
})`

const rtdal001419Source0005 = `test_that("cur_data() and cur_data_all() work sequentially", {
  options(lifecycle_verbosity = "quiet")

  df <- tibble(a = 1)
  expect_equal(
    mutate(df, x = df_n_col(cur_data()), y = df_n_col(cur_data())),
    tibble(a = 1, x = 1, y = 2)
  )

  gf <- tibble(a = 1, b = 2) |> group_by(a)
  expect_equal(
    mutate(gf, x = df_n_col(cur_data_all()), y = df_n_col(cur_data_all())),
    group_by(tibble(a = 1, b = 2, x = 2, y = 3), a)
  )
})`

const rtdal001419Source0006 = `test_that("mutate(=NULL) preserves correct all_vars", {
  options(lifecycle_verbosity = "quiet")

  df <- data.frame(x = 1, y = 2) |>
    mutate(x = NULL, vars = cur_data_all()) |>
    pull()
  expect_equal(df, tibble(y = 2))
})`

