const rtdal001423Source0001 = `test_that("distinct equivalent to local unique when keep_all is TRUE", {
  df <- data.frame(
    x = c(1, 1, 1, 1),
    y = c(1, 1, 2, 2),
    z = c(1, 2, 1, 2)
  )

  expect_equal(distinct(df), unique(df))
})`

const rtdal001423Source0002 = `test_that("distinct for single column works as expected (#1937)", {
  df <- tibble(
    x = c(1, 1, 1, 1),
    y = c(1, 1, 2, 2),
    z = c(1, 2, 1, 2)
  )

  expect_equal(distinct(df, x, .keep_all = FALSE), unique(df["x"]))
  expect_equal(distinct(df, y, .keep_all = FALSE), unique(df["y"]))
})`

const rtdal001423Source0003 = `test_that("distinct works for 0-sized columns (#1437)", {
  df <- tibble(x = 1:10) |> select(-x)
  ddf <- distinct(df)
  expect_equal(df_n_col(ddf), 0L)
})`

const rtdal001423Source0004 = `test_that("if no variables specified, uses all", {
  df <- tibble(x = c(1, 1), y = c(2, 2))
  expect_equal(distinct(df), tibble(x = 1, y = 2))
})`

const rtdal001423Source0005 = `test_that("distinct keeps only specified cols", {
  df <- tibble(x = c(1, 1, 1), y = c(1, 1, 1))
  expect_equal(df |> distinct(x), tibble(x = 1))
})`

const rtdal001423Source0006 = `test_that("unless .keep_all = TRUE", {
  df <- tibble(x = c(1, 1, 1), y = 3:1)

  expect_equal(df |> distinct(x), tibble(x = 1))
  expect_equal(df |> distinct(x, .keep_all = TRUE), tibble(x = 1, y = 3L))
})`

const rtdal001423Source0007 = `test_that("distinct doesn't duplicate columns", {
  df <- tibble(a = 1:3, b = 4:6)

  expect_named(df |> distinct(a, a), "a")
  expect_named(df |> group_by(a) |> distinct(a), "a")
})`

const rtdal001423Source0008 = `test_that("grouped distinct always includes group cols", {
  df <- tibble(g = c(1, 2), x = c(1, 2))

  out <- df |> group_by(g) |> distinct(x)
  expect_named(out, c("g", "x"))
})`

const rtdal001423Source0009 = `test_that("empty grouped distinct equivalent to empty ungrouped", {
  df <- tibble(g = c(1, 2), x = c(1, 2))

  df1 <- df |> distinct() |> group_by(g)
  df2 <- df |> group_by(g) |> distinct()

  expect_equal(df1, df2)
})`

const rtdal001423Source0010 = `test_that("distinct on a new, mutated variable is equivalent to mutate followed by distinct", {
  df <- tibble(g = c(1, 2), x = c(1, 2))

  df1 <- df |> distinct(aa = g * 2)
  df2 <- df |> mutate(aa = g * 2) |> distinct(aa)

  expect_equal(df1, df2)
})`

const rtdal001423Source0011 = `test_that("distinct on a new, copied variable is equivalent to mutate followed by distinct (#3234)", {
  df <- tibble(g = c(1, 2), x = c(1, 2))

  df1 <- df |> distinct(aa = g)
  df2 <- df |> mutate(aa = g) |> distinct(aa)

  expect_equal(df1, df2)
})`

const rtdal001423Source0012 = `test_that("distinct on a dataframe or tibble with columns of type list throws an error", {
  df <- tibble(
    a = c("1", "1", "2", "2", "3", "3"),
    b = list("A")
  )
  df2 <- data.frame(x = 1:5, y = I(list(1:3, 2:4, 3:5, 4:6, 5:7)))

  expect_identical(df2 |> distinct(), df2)
  expect_identical(df |> distinct(), df |> slice(c(1, 3, 5)))
})`

const rtdal001423Source0013 = `test_that("distinct handles 0 columns edge case (#2954)", {
  d <- select(data.frame(x = c(1, 1)), one_of(character(0)))
  res <- distinct(d)
  expect_equal(nrow(res), 1L)

  expect_equal(nrow(distinct(tibble())), 0L)
})`

const rtdal001423Source0014 = `test_that("distinct respects order of the specified variables (#3195, #6156)", {
  d <- data.frame(x = 1:2, y = 3:4)
  expect_named(distinct(d, y, x), c("y", "x"))
})`

const rtdal001423Source0015 = `test_that("distinct adds grouping variables to front if missing", {
  d <- data.frame(x = 1:2, y = 3:4)
  expect_named(distinct(group_by(d, y), x), c("y", "x"))
  expect_named(distinct(group_by(d, y), x, y), c("x", "y"))
})`

const rtdal001423Source0016 = `test_that("distinct() understands both NA variants (#4516)", {
  df <- data.frame(col_a = c(1, NA, NA))
  df$col_a <- df$col_a + 0
  df$col_a[2] <- NA_real_
  expect_equal(nrow(distinct(df)), 2L)

  df_1 <- data.frame(col_a = c(1, NA))
  df_2 <- data.frame(col_a = c(1, NA))

  df_1$col_a <- df_1$col_a + 0
  df_2$col_a <- df_2$col_a + 0

  df_1$col_a[2] <- NA
  expect_equal(nrow(setdiff(df_1, df_2)), 0L)
})`

const rtdal001423Source0017 = `test_that("distinct() handles auto splicing", {
  expect_equal(
    iris |> distinct(Species),
    iris |> distinct(data.frame(Species = Species))
  )

  expect_equal(
    iris |> distinct(Species),
    iris |> distinct(pick(Species))
  )

  expect_equal(
    iris |>
      mutate(across(starts_with("Sepal"), round)) |>
      distinct(Sepal.Length, Sepal.Width),
    iris |> distinct(across(starts_with("Sepal"), round))
  )
})`

const rtdal001423Source0018 = `test_that("distinct preserves grouping", {
  gf <- group_by(tibble(x = c(1, 1, 2, 2), y = x), x)

  i <- count_regroups(out <- distinct(gf))
  expect_equal(i, 0)
  expect_equal(group_vars(out), "x")

  i <- count_regroups(out <- distinct(gf, x = x + 2))
  expect_equal(i, 1)
  expect_equal(group_vars(out), "x")
})`

const rtdal001423Source0019 = `test_that("distinct() preserves attributes on bare data frames (#6318)", {
  df <- vctrs::data_frame(x = c(1, 1))
  attr(df, "foo") <- "bar"

  out <- distinct(df, x)
  expect_identical(attr(out, "foo"), "bar")

  out <- distinct(df, y = x + 1L)
  expect_identical(attr(out, "foo"), "bar")
})`

const rtdal001423Source0020 = `test_that("distinct errors when selecting an unknown column (#3140)", {
  expect_snapshot({
    df <- tibble(g = c(1, 2), x = c(1, 2))

    (expect_error(df |> distinct(aa, x)))
    (expect_error(df |> distinct(aa, bb)))
    (expect_error(df |> distinct(.data$aa)))

    (expect_error(df |> distinct(y = a + 1)))
  })
})`

