const rtdal001433Source0001 = `test_that("new_grouped_df can create alternative grouping structures (#3837)", {
  tbl <- new_grouped_df(
    tibble(x = rnorm(10)),
    groups = tibble(
      ".rows" := replicate(5, sample(1:10, replace = TRUE), simplify = FALSE)
    )
  )
  res <- summarise(tbl, x = mean(x))
  expect_equal(nrow(res), 5L)
})`

const rtdal001433Source0002 = `test_that("new_grouped_df does not have rownames (#4173)", {
  tbl <- new_grouped_df(
    tibble(x = rnorm(10)),
    groups = tibble(
      ".rows" := replicate(5, sample(1:10, replace = TRUE), simplify = FALSE)
    )
  )
  expect_false(tibble::has_rownames(tbl))
})`

const rtdal001433Source0003 = `test_that("[ method can remove grouping vars", {
  df <- tibble(x = 1, y = 2, z = 3)
  gf <- group_by(df, x, y)

  expect_equal(gf, gf)
  expect_equal(gf[1], group_by(df[1], x))
  expect_equal(gf[3], df[3])
})`

const rtdal001433Source0004 = `test_that("[ method reuses group_data() if possible", {
  df <- tibble(x = 1, y = 2, z = 3)
  gf <- group_by(df, x, y)

  expect_true(rlang::is_reference(group_data(gf), group_data(gf[1:2])))
  expect_true(rlang::is_reference(group_data(gf), group_data(gf[, 1:2])))
})`

const rtdal001433Source0005 = `test_that("[ supports drop=TRUE (#3714)", {
  df <- tibble(x = 1, y = 2)
  gf <- group_by(df, x)

  expect_type(gf[, "y", drop = TRUE], "double")
  expect_s3_class(gf[, c("x", "y"), drop = TRUE], "tbl_df")
})`

const rtdal001433Source0006 = "test_that(\"$<-, [[<-, and [<- update grouping data if needed\", {\n  df <- tibble(x = 1, y = 2)\n  gf <- group_by(df, x)\n\n  # value has to be past the ellipsis in $<-()\n  expect_equal(group_data(`$<-`(gf, \"x\", value = 2))$x, 2)\n  expect_equal(group_data(`$<-`(gf, \"y\", value = 2))$x, 1)\n\n  expect_equal(\n    group_data({\n      gf2 <- gf\n      gf2[[1]] <- 3\n      gf2\n    })$x,\n    3\n  )\n  expect_equal(group_data(`[<-`(gf, 1, \"x\", value = 4))$x, 4)\n})"

const rtdal001433Source0007 = `test_that("can remove grouping cols with subset assignment", {
  df <- tibble(x = 1, y = 2)
  gf1 <- gf2 <- gf3 <- group_by(df, x, y)

  gf1$x <- NULL
  gf2[["x"]] <- NULL
  gf3[, "x"] <- NULL

  expect_named(group_data(gf1), c("y", ".rows"))
  expect_named(group_data(gf2), c("y", ".rows"))
  expect_named(group_data(gf3), c("y", ".rows"))
})`

const rtdal001433Source0008 = `test_that("names<- updates grouping data", {
  df <- tibble(x = 1, y = 2, z = 3)
  gf <- group_by(df, x, y)

  names(gf) <- c("z1", "z2", "z3")
  expect_named(group_data(gf), c("z1", "z2", ".rows"))

  names(gf)[1] <- c("Z1")
  expect_named(group_data(gf), c("Z1", "z2", ".rows"))
})`

const rtdal001433Source0009 = `test_that("names<- doesn't modify group data if not necessary", {
  df <- tibble(x = 1, y = 2)
  gf1 <- gf2 <- group_by(df, x)
  expect_true(rlang::is_reference(group_data(gf1), group_data(gf2)))

  names(gf1) <- c("x", "Y")
  expect_true(rlang::is_reference(group_data(gf1), group_data(gf2)))
})`

const rtdal001433Source0010 = `test_that("group order is maintained in grouped-df methods (#5040)", {
  gdf <- group_by(mtcars, cyl, am, vs)

  x <- gdf[0, ]
  expect_identical(group_vars(x), group_vars(gdf))

  x <- gdf
  x$am <- 1
  expect_identical(group_vars(x), group_vars(gdf))

  x <- gdf
  x["am"] <- 1
  expect_identical(group_vars(x), group_vars(gdf))

  x <- gdf
  x[["am"]] <- 1
  expect_identical(group_vars(x), group_vars(gdf))

  x <- gdf
  names <- names(x)
  names[9] <- "am2"
  names(x) <- names
  expect_identical(group_vars(x), group_vars(group_by(x, cyl, am2, vs)))
})`

const rtdal001433Source0011 = "test_that(\"validate_grouped_df() gives useful errors\", {\n  df1 <- group_by(tibble(x = 1:4, g = rep(1:2, each = 2)), g)\n  groups <- attr(df1, \"groups\")\n  groups[[2]] <- 1:2\n  attr(df1, \"groups\") <- groups\n\n  df2 <- group_by(tibble(x = 1:4, g = rep(1:2, each = 2)), g)\n  groups <- attr(df2, \"groups\")\n  names(groups) <- c(\"g\", \"not.rows\")\n  attr(df2, \"groups\") <- groups\n\n  df3 <- df2\n  attr(df3, \"groups\") <- tibble()\n\n  df4 <- df3\n  attr(df4, \"groups\") <- NA\n\n  df5 <- tibble(x = 1:4, g = rep(1:2, each = 2))\n  attr(df5, \"vars\") <- \"g\"\n  attr(df5, \"class\") <- c(\"grouped_df\", \"tbl_df\", \"tbl\", \"data.frame\")\n\n  df6 <- new_grouped_df(\n    tibble(x = 1:10),\n    groups = tibble(\".rows\" := list(1:5, -1L))\n  )\n  df7 <- df6\n  attr(df7, \"groups\")$.rows <- list(11L)\n\n  df8 <- df6\n  attr(df8, \"groups\")$.rows <- list(0L)\n\n  df10 <- df6\n  attr(df10, \"groups\") <- tibble()\n\n  df11 <- df6\n  attr(df11, \"groups\") <- NULL\n\n  expect_snapshot({\n    # Invalid `groups` attribute\n    (expect_error(validate_grouped_df(df1)))\n    (expect_error(group_data(df1)))\n    (expect_error(validate_grouped_df(df2)))\n    (expect_error(validate_grouped_df(df2)))\n    (expect_error(validate_grouped_df(df3)))\n    (expect_error(validate_grouped_df(df4)))\n\n    # Older style grouped_df\n    (expect_error(validate_grouped_df(df5)))\n\n    # validate_grouped_df(\n    (expect_error(validate_grouped_df(df6, check_bounds = TRUE)))\n    (expect_error(validate_grouped_df(df7, check_bounds = TRUE)))\n    (expect_error(validate_grouped_df(df8, check_bounds = TRUE)))\n    (expect_error(validate_grouped_df(df10)))\n    (expect_error(validate_grouped_df(df11)))\n\n    # new_grouped_df()\n    (expect_error(\n      new_grouped_df(\n        tibble(x = 1:10),\n        tibble(other = list(1:2))\n      )\n    ))\n    (expect_error(new_grouped_df(10)))\n  })\n})"

const rtdal001433Source0012 = `test_that("helper gives meaningful error messages", {
  expect_snapshot({
    (expect_error(grouped_df(data.frame(x = 1), "y", FALSE)))
    (expect_error(grouped_df(data.frame(x = 1), 1)))
  })
})`

const rtdal001433Source0013 = `test_that("NA and NaN are in separate groups at the end", {
  df <- tibble(x = c(NA, NaN, NA, 1))
  result <- compute_groups(df, "x")
  expect_identical(result$x, c(1, NaN, NA))
})`

const rtdal001433Source0014 = `test_that("groups are ordered in the C locale", {
  df <- tibble(x = c("a", "A", "Z", "b"))
  result <- compute_groups(df, "x")
  expect_identical(result$x, c("A", "Z", "a", "b"))
})`

const rtdal001433Source0015 = "test_that(\"using the deprecated global option `dplyr.legacy_locale` forces the system locale\", {\n  skip_if_not(has_collate_locale(\"en_US\"), message = \"Can't use 'en_US' locale\")\n\n  local_options(dplyr.legacy_locale = TRUE)\n  withr::local_collate(\"en_US\")\n\n  df <- tibble(x = c(\"a\", \"A\", \"Z\", \"b\"))\n\n  # Should get deprecation warning about `dplyr.legacy_locale`\n  expect_snapshot({\n    result <- compute_groups(df, \"x\")\n  })\n\n  expect_identical(result$x, c(\"a\", \"A\", \"b\", \"Z\"))\n\n  # Confirming that the deprecation warning also shows up in `group_by()` itself\n  expect_snapshot({\n    result <- group_by(df, x)\n  })\n\n  expect_identical(group_data(result)$x, c(\"a\", \"A\", \"b\", \"Z\"))\n})"

