const rtdal001440Source0001 = `test_that("mutating joins preserve row and column order of x", {
  df1 <- data.frame(a = 1:3)
  df2 <- data.frame(b = 1, c = 2, a = 4:1)

  out <- inner_join(df1, df2, by = "a")
  expect_named(out, c("a", "b", "c"))
  expect_equal(out$a, 1:3)

  out <- left_join(df1, df2, by = "a")
  expect_named(out, c("a", "b", "c"))
  expect_equal(out$a, 1:3)

  out <- right_join(df1, df2, by = "a")
  expect_named(out, c("a", "b", "c"))
  expect_equal(out$a, 1:4)

  out <- full_join(df1, df2, by = "a")
  expect_named(out, c("a", "b", "c"))
  expect_equal(out$a, 1:4)
})`

const rtdal001440Source0002 = `test_that("even when column names change", {
  df1 <- data.frame(x = c(1, 1, 2, 3), z = 1:4, a = 1)
  df2 <- data.frame(z = 1:3, b = 1, x = c(1, 2, 4))

  out <- inner_join(df1, df2, by = "x")
  expect_named(out, c("x", "z.x", "a", "z.y", "b"))
})`

const rtdal001440Source0003 = `test_that("filtering joins preserve row and column order of x (#2964)", {
  df1 <- data.frame(a = 4:1, b = 1)
  df2 <- data.frame(b = 1, c = 2, a = 2:3)

  out <- semi_join(df1, df2, by = "a")
  expect_named(out, c("a", "b"))
  expect_equal(out$a, 3:2)

  out <- anti_join(df1, df2, by = "a")
  expect_named(out, c("a", "b"))
  expect_equal(out$a, c(4L, 1L))
})`

const rtdal001440Source0004 = `test_that("keys are coerced to symmetric type", {
  foo <- tibble(id = 1:2, var1 = "foo")
  bar <- tibble(id = as.numeric(1:2), var2 = "bar")
  expect_type(inner_join(foo, bar, by = "id")$id, "double")
  expect_type(inner_join(bar, foo, by = "id")$id, "double")

  foo <- tibble(id = factor(c("a", "b")), var1 = "foo")
  bar <- tibble(id = c("a", "b"), var2 = "bar")
  expect_type(inner_join(foo, bar, by = "id")$id, "character")
  expect_type(inner_join(bar, foo, by = "id")$id, "character")
})`

const rtdal001440Source0005 = `test_that("factor keys are coerced to the union factor type", {
  df1 <- tibble(x = 1, y = factor("a"))
  df2 <- tibble(x = 2, y = factor("b"))
  out <- full_join(df1, df2, by = c("x", "y"))
  expect_equal(out$y, factor(c("a", "b")))
})`

const rtdal001440Source0006 = "test_that(\"keys of non-equi conditions are not coerced if `keep = NULL`\", {\n  foo <- tibble(id = factor(c(\"a\", \"b\")), col1 = c(1, 2), var1 = \"foo\")\n  bar <- tibble(id = c(\"a\", \"b\"), col2 = c(1L, 2L), var2 = \"bar\")\n\n  out <- inner_join(foo, bar, by = join_by(id, col1 >= col2))\n  expect_type(out$id, \"character\")\n  expect_type(out$col1, \"double\")\n  expect_type(out$col2, \"integer\")\n\n  out <- inner_join(bar, foo, by = join_by(id, col2 <= col1))\n  expect_type(out$id, \"character\")\n  expect_type(out$col1, \"double\")\n  expect_type(out$col2, \"integer\")\n})"

const rtdal001440Source0007 = `test_that("when keep = TRUE, left_join() preserves both sets of keys", {
  # when keys have different names
  df1 <- tibble(a = c(2, 3), b = c(1, 2))
  df2 <- tibble(x = c(3, 4), y = c(3, 4))
  out <- left_join(df1, df2, by = c("a" = "x"), keep = TRUE)
  expect_equal(out$a, c(2, 3))
  expect_equal(out$x, c(NA, 3))

  # when keys have same name
  df1 <- tibble(a = c(2, 3), b = c(1, 2))
  df2 <- tibble(a = c(3, 4), y = c(3, 4))
  out <- left_join(df1, df2, by = c("a"), keep = TRUE)
  expect_equal(out$a.x, c(2, 3))
  expect_equal(out$a.y, c(NA, 3))
})`

const rtdal001440Source0008 = `test_that("when keep = TRUE, right_join() preserves both sets of keys", {
  # when keys have different names
  df1 <- tibble(a = c(2, 3), b = c(1, 2))
  df2 <- tibble(x = c(3, 4), y = c(3, 4))
  out <- right_join(df1, df2, by = c("a" = "x"), keep = TRUE)
  expect_equal(out$a, c(3, NA))
  expect_equal(out$x, c(3, 4))

  # when keys have same name
  df1 <- tibble(a = c(2, 3), b = c(1, 2))
  df2 <- tibble(a = c(3, 4), y = c(3, 4))
  out <- right_join(df1, df2, by = c("a"), keep = TRUE)
  expect_equal(out$a.x, c(3, NA))
  expect_equal(out$a.y, c(3, 4))
})`

const rtdal001440Source0009 = `test_that("when keep = TRUE, full_join() preserves both sets of keys", {
  # when keys have different names
  df1 <- tibble(a = c(2, 3), b = c(1, 2))
  df2 <- tibble(x = c(3, 4), y = c(3, 4))
  out <- full_join(df1, df2, by = c("a" = "x"), keep = TRUE)
  expect_equal(out$a, c(2, 3, NA))
  expect_equal(out$x, c(NA, 3, 4))

  # when keys have same name
  df1 <- tibble(a = c(2, 3), b = c(1, 2))
  df2 <- tibble(a = c(3, 4), y = c(3, 4))
  out <- full_join(df1, df2, by = c("a"), keep = TRUE)
  expect_equal(out$a.x, c(2, 3, NA))
  expect_equal(out$a.y, c(NA, 3, 4))
})`

const rtdal001440Source0010 = `test_that("when keep = TRUE, inner_join() preserves both sets of keys (#5581)", {
  # when keys have different names
  df1 <- tibble(a = c(2, 3), b = c(1, 2))
  df2 <- tibble(x = c(3, 4), y = c(3, 4))
  out <- inner_join(df1, df2, by = c("a" = "x"), keep = TRUE)
  expect_equal(out$a, c(3))
  expect_equal(out$x, c(3))

  # when keys have same name
  df1 <- tibble(a = c(2, 3), b = c(1, 2))
  df2 <- tibble(a = c(3, 4), y = c(3, 4))
  out <- inner_join(df1, df2, by = c("a"), keep = TRUE)
  expect_equal(out$a.x, c(3))
  expect_equal(out$a.y, c(3))
})`

const rtdal001440Source0011 = "test_that(\"can't use `keep = FALSE` with non-equi conditions (#6499)\", {\n  df1 <- tibble(xl = c(1, 3), xu = c(4, 7))\n  df2 <- tibble(yl = c(2, 5, 8), yu = c(6, 8, 9))\n\n  expect_snapshot(error = TRUE, {\n    left_join(df1, df2, join_by(overlaps(xl, xu, yl, yu)), keep = FALSE)\n  })\n\n  # Would never make sense here.\n  # Based on how the binary conditions are generated we'd merge:\n  # - `yu` into `xl`\n  # - `yl` into `xu`\n  # Which results in `xl` and `xu` columns that don't maintain `xl <= xu`.\n  expect_snapshot(error = TRUE, {\n    full_join(df1, df2, join_by(overlaps(xl, xu, yl, yu)), keep = FALSE)\n  })\n})"

const rtdal001440Source0012 = `test_that("joins matches NAs by default (#892, #2033)", {
  df1 <- tibble(x = c(NA_character_, 1))
  df2 <- tibble(x = c(NA_character_, 2))

  expect_equal(nrow(inner_join(df1, df2, by = "x")), 1)
  expect_equal(nrow(semi_join(df1, df2, by = "x")), 1)
})`

const rtdal001440Source0013 = `test_that("joins don't match NA when na_matches = 'never' (#2033)", {
  df1 <- tibble(a = c(1, NA))
  df2 <- tibble(a = c(1, NA), b = 1:2)

  out <- left_join(df1, df2, by = "a", na_matches = "never")
  expect_equal(out, tibble(a = c(1, NA), b = c(1, NA)))

  out <- inner_join(df1, df2, by = "a", na_matches = "never")
  expect_equal(out, tibble(a = 1, b = 1))

  out <- semi_join(df1, df2, by = "a", na_matches = "never")
  expect_equal(out, tibble(a = 1))

  out <- anti_join(df1, df2, by = "a", na_matches = "never")
  expect_equal(out, tibble(a = NA_integer_))

  out <- nest_join(df1, df2, by = "a", na_matches = "never")
  expect <- tibble(
    a = c(1, NA),
    df2 = list(tibble(b = 1L), tibble(b = integer()))
  )
  expect_equal(out, expect)

  dat1 <- tibble(
    name = c("a", "c"),
    var1 = c(1, 2)
  )
  dat3 <- tibble(
    name = c("a", NA_character_),
    var3 = c(5, 6)
  )
  expect_equal(
    full_join(dat1, dat3, by = "name", na_matches = "never"),
    tibble(name = c("a", "c", NA), var1 = c(1, 2, NA), var3 = c(5, NA, 6))
  )
})`

const rtdal001440Source0014 = "test_that(\"`left_join(by = join_by(closest(...)))` works as expected\", {\n  df1 <- tibble(x = 1:5)\n  df2 <- tibble(y = c(1, 2, 4))\n\n  out <- left_join(df1, df2, by = join_by(closest(x <= y)))\n  expect_identical(out$x, 1:5)\n  expect_identical(out$y, c(1, 2, 4, 4, NA))\n\n  out <- left_join(df1, df2, by = join_by(closest(x < y)))\n  expect_identical(out$x, 1:5)\n  expect_identical(out$y, c(2, 4, 4, NA, NA))\n\n  out <- left_join(df1, df2, by = join_by(closest(x >= y)))\n  expect_identical(out$x, 1:5)\n  expect_identical(out$y, c(1, 2, 2, 4, 4))\n\n  out <- left_join(df1, df2, by = join_by(closest(x > y)))\n  expect_identical(out$x, 1:5)\n  expect_identical(out$y, c(NA, 1, 2, 2, 4))\n})"

const rtdal001440Source0015 = "test_that(\"`full_join(by = join_by(closest(...)))` works as expected\", {\n  df1 <- tibble(x = 1:5)\n  df2 <- tibble(y = c(1, 2, 4))\n\n  out <- full_join(df1, df2, by = join_by(closest(x <= y)))\n  expect_identical(out$x, 1:5)\n  expect_identical(out$y, c(1, 2, 4, 4, NA))\n\n  out <- full_join(df1, df2, by = join_by(closest(x < y)))\n  expect_identical(out$x, c(1:5, NA))\n  expect_identical(out$y, c(2, 4, 4, NA, NA, 1))\n\n  out <- full_join(df1, df2, by = join_by(closest(x >= y)))\n  expect_identical(out$x, 1:5)\n  expect_identical(out$y, c(1, 2, 2, 4, 4))\n\n  out <- full_join(df1, df2, by = join_by(closest(x > y)))\n  expect_identical(out$x, 1:5)\n  expect_identical(out$y, c(NA, 1, 2, 2, 4))\n})"

const rtdal001440Source0016 = "test_that(\"`right_join(by = join_by(closest(...)))` works as expected\", {\n  df1 <- tibble(x = 1:5)\n  df2 <- tibble(y = c(1, 2, 4))\n\n  out <- right_join(df1, df2, by = join_by(closest(x <= y)))\n  expect_identical(out$x, 1:4)\n  expect_identical(out$y, c(1, 2, 4, 4))\n\n  out <- right_join(df1, df2, by = join_by(closest(x < y)))\n  expect_identical(out$x, c(1:3, NA))\n  expect_identical(out$y, c(2, 4, 4, 1))\n\n  out <- right_join(df1, df2, by = join_by(closest(x >= y)))\n  expect_identical(out$x, 1:5)\n  expect_identical(out$y, c(1, 2, 2, 4, 4))\n\n  out <- right_join(df1, df2, by = join_by(closest(x > y)))\n  expect_identical(out$x, 2:5)\n  expect_identical(out$y, c(1, 2, 2, 4))\n})"

const rtdal001440Source0017 = "test_that(\"`inner_join(by = join_by(closest(...)))` works as expected\", {\n  df1 <- tibble(x = 1:5)\n  df2 <- tibble(y = c(1, 2, 4))\n\n  out <- inner_join(df1, df2, by = join_by(closest(x <= y)))\n  expect_identical(out$x, 1:4)\n  expect_identical(out$y, c(1, 2, 4, 4))\n\n  out <- inner_join(df1, df2, by = join_by(closest(x < y)))\n  expect_identical(out$x, 1:3)\n  expect_identical(out$y, c(2, 4, 4))\n\n  out <- inner_join(df1, df2, by = join_by(closest(x >= y)))\n  expect_identical(out$x, 1:5)\n  expect_identical(out$y, c(1, 2, 2, 4, 4))\n\n  out <- inner_join(df1, df2, by = join_by(closest(x > y)))\n  expect_identical(out$x, 2:5)\n  expect_identical(out$y, c(1, 2, 2, 4))\n})"

const rtdal001440Source0018 = "test_that(\"joins using `between(bounds =)` work as expected (#6488)\", {\n  df1 <- tibble(x = 1:5)\n  df2 <- tibble(lower = 2, upper = 4)\n\n  out <- full_join(\n    df1,\n    df2,\n    by = join_by(between(x, lower, upper, bounds = \"[]\"))\n  )\n  expect_identical(out$lower, c(NA, 2, 2, 2, NA))\n  expect_identical(out$upper, c(NA, 4, 4, 4, NA))\n\n  out <- full_join(\n    df1,\n    df2,\n    by = join_by(between(x, lower, upper, bounds = \"[)\"))\n  )\n  expect_identical(out$lower, c(NA, 2, 2, NA, NA))\n  expect_identical(out$upper, c(NA, 4, 4, NA, NA))\n\n  out <- full_join(\n    df1,\n    df2,\n    by = join_by(between(x, lower, upper, bounds = \"(]\"))\n  )\n  expect_identical(out$lower, c(NA, NA, 2, 2, NA))\n  expect_identical(out$upper, c(NA, NA, 4, 4, NA))\n\n  out <- full_join(\n    df1,\n    df2,\n    by = join_by(between(x, lower, upper, bounds = \"()\"))\n  )\n  expect_identical(out$lower, c(NA, NA, 2, NA, NA))\n  expect_identical(out$upper, c(NA, NA, 4, NA, NA))\n})"

const rtdal001440Source0019 = "test_that(\"joins using `overlaps(bounds =)` work as expected (#6488)\", {\n  df1 <- tibble(x_lower = c(1, 1, 3, 4), x_upper = c(2, 3, 4, 5))\n  df2 <- tibble(y_lower = 2, y_upper = 4)\n\n  expect_closed <- vec_cbind(df1, vec_c(df2, df2, df2, df2))\n\n  out <- full_join(\n    df1,\n    df2,\n    by = join_by(overlaps(x_lower, x_upper, y_lower, y_upper, bounds = \"[]\"))\n  )\n  expect_identical(out, expect_closed)\n\n  # `[)`, `(]`, and `()` all generate the same binary conditions but are useful\n  # for consistency with `between(bounds =)`\n  expect_open <- vec_cbind(df1, vec_c(NA, df2, df2, NA))\n\n  out <- full_join(\n    df1,\n    df2,\n    by = join_by(overlaps(x_lower, x_upper, y_lower, y_upper, bounds = \"[)\"))\n  )\n  expect_identical(out, expect_open)\n  out <- full_join(\n    df1,\n    df2,\n    by = join_by(overlaps(x_lower, x_upper, y_lower, y_upper, bounds = \"(]\"))\n  )\n  expect_identical(out, expect_open)\n  out <- full_join(\n    df1,\n    df2,\n    by = join_by(overlaps(x_lower, x_upper, y_lower, y_upper, bounds = \"()\"))\n  )\n  expect_identical(out, expect_open)\n})"

