const rtdal001440Source0049 = "test_that(\"`by = character()` technically respects `relationship`\", {\n  local_options(lifecycle_verbosity = \"quiet\")\n\n  df <- tibble(x = 1:2)\n\n  expect_snapshot(error = TRUE, {\n    left_join(df, df, by = character(), relationship = \"many-to-one\")\n  })\n})"

const rtdal001440Source0050 = "test_that(\"`by = character()` for a cross join is deprecated (#6604)\", {\n  df1 <- tibble(x = 1:2)\n  df2 <- tibble(y = 1:2)\n\n  # Mutating join\n  expect_snapshot({\n    out <- left_join(df1, df2, by = character())\n  })\n\n  # Filtering join\n  expect_snapshot({\n    out <- semi_join(df1, df2, by = character())\n  })\n\n  # Nest join\n  expect_snapshot({\n    out <- nest_join(df1, df2, by = character())\n  })\n})"

const rtdal001440Source0051 = "test_that(\"`by = named character()` for a cross join works\", {\n  # Used by the sift package\n  df1 <- tibble(x = 1:2)\n  df2 <- tibble(y = 1:2)\n\n  by <- set_names(character(), nm = character())\n\n  expect_snapshot({\n    out <- left_join(df1, df2, by = by)\n  })\n  expect_identical(\n    out,\n    cross_join(df1, df2)\n  )\n})"

const rtdal001440Source0052 = "test_that(\"`by = list(x = character(), y = character())` for a cross join is deprecated (#6604)\", {\n  df1 <- tibble(x = 1:2)\n  df2 <- tibble(y = 1:2)\n\n  expect_snapshot({\n    out <- left_join(df1, df2, by = list(x = character(), y = character()))\n  })\n})"

