const rtdal001443Source0067 = `test_that("mutate() give meaningful errors", {
  expect_snapshot({
    tbl <- tibble(x = 1:2, y = 1:2)

    # setting column to NULL makes it unavailable
    (expect_error(tbl |> mutate(y = NULL, a = sum(y))))
    (expect_error(
      tbl |>
        group_by(x) |>
        mutate(y = NULL, a = sum(y))
    ))

    # incompatible column type
    (expect_error(tibble(x = 1) |> mutate(y = mean)))

    # Unsupported type"
    df <- tibble(g = c(1, 1, 2, 2, 2), x = 1:5)
    (expect_error(df |> mutate(out = env(a = 1))))
    (expect_error(
      df |>
        group_by(g) |>
        mutate(out = env(a = 1))
    ))
    (expect_error(
      df |>
        rowwise() |>
        mutate(out = rnorm)
    ))

    # incompatible types across groups
    (expect_error(
      data.frame(x = rep(1:5, each = 3)) |>
        group_by(x) |>
        mutate(val = ifelse(x < 3, "foo", 2))
    ))

    # mixed nulls
    (expect_error(
      tibble(a = 1:3, b = 4:6) |>
        group_by(a) |>
        mutate(if (a == 1) NULL else "foo")
    ))
    (expect_error(
      tibble(a = 1:3, b = 4:6) |>
        group_by(a) |>
        mutate(if (a == 2) NULL else "foo")
    ))

    # incompatible size
    (expect_error(
      data.frame(x = c(2, 2, 3, 3)) |> mutate(int = 1:5)
    ))
    (expect_error(
      data.frame(x = c(2, 2, 3, 3)) |>
        group_by(x) |>
        mutate(int = 1:5)
    ))
    (expect_error(
      data.frame(x = c(2, 3, 3)) |>
        group_by(x) |>
        mutate(int = 1:5)
    ))
    (expect_error(
      data.frame(x = c(2, 2, 3, 3)) |>
        rowwise() |>
        mutate(int = 1:5)
    ))
    (expect_error(
      tibble(y = list(1:3, "a")) |>
        rowwise() |>
        mutate(y2 = y)
    ))
    (expect_error(
      data.frame(x = 1:10) |> mutate(y = 11:20, y = 1:2)
    ))

    # .data pronoun
    (expect_error(
      tibble(a = 1) |> mutate(c = .data$b)
    ))
    (expect_error(
      tibble(a = 1:3) |>
        group_by(a) |>
        mutate(c = .data$b)
    ))

    # obsolete data mask
    lazy <- function(x) list(enquo(x))
    res <- tbl |>
      rowwise() |>
      mutate(z = lazy(x), .keep = "unused")
    (expect_error(
      eval_tidy(res$z[[1]])
    ))

    # Error that contains {
    (expect_error(
      tibble() |> mutate(stop("{"))
    ))
  })
})`

