const rtdal001445Source0004 = "test_that(\"missing values are allowed to equal each other, so `NaN`s can be standardized\", {\n  expect_identical(na_if(NaN, NaN), NA_real_)\n})"

const rtdal001445Source0005 = `test_that("missing values equal each other in partially incomplete data frame rows", {
  x <- tibble(
    x = c(2, 1, NA, 1),
    y = c(1, NA, NA, NA),
    z = c(3, NaN, NA, NaN)
  )

  y <- tibble(x = 1, y = NA, z = NaN)

  expect <- vec_assign(x, i = c(2, 4), value = NA)

  expect_identical(na_if(x, y), expect)
})`

const rtdal001445Source0006 = `test_that("works when there are missings in either input", {
  expect_identical(na_if(c(1, NA, 2), 1), c(NA, NA, 2))
  expect_identical(na_if(c(1, NA, 2), c(1, NA, NA)), c(NA, NA, 2))
})`

const rtdal001445Source0007 = `test_that("works with data frames", {
  x <- tibble(a = c(1, 99, 99, 99), b = c("x", "NA", "bar", "NA"))
  y <- tibble(a = 99, b = "NA")

  expect_identical(
    na_if(x, y),
    x[c(1, NA, 3, NA), ]
  )
})`

