const rtdal001448Source0001 = "test_that(\"nth works with lists and uses `vec_slice2()` to return elements (#6331)\", {\n  # We'd like to use `vec_slice()` everywhere, but it breaks too many revdeps\n  # that rely on `nth(<list>)` returning list elements\n  x <- list(1, 2, 3:5)\n\n  expect_equal(nth(x, 1), 1)\n  expect_equal(nth(x, 3), 3:5)\n})"

const rtdal001448Source0002 = "test_that(\"nth `default` for lists defaults to `NULL` since it uses `vec_slice2()`\", {\n  expect_null(nth(list(1), 2))\n  expect_null(nth(list(), 1))\n})"

const rtdal001448Source0003 = "test_that(\"nth `default` for lists can be anything\", {\n  # Because list elements can be anything\n  x <- list(1, 2)\n\n  default <- environment()\n  expect_identical(nth(x, 3, default = default), default)\n\n  default <- 1:3\n  expect_identical(nth(x, 3, default = default), default)\n})"

const rtdal001448Source0004 = "test_that(\"nth treats list-of like lists\", {\n  x <- list_of(1, 2, c(3, 4))\n\n  expect_identical(nth(x, 3), c(3, 4))\n  expect_identical(nth(x, 4), NULL)\n\n  # Not particularly strict about `default` here,\n  # even though `list_of()` elements are typed\n  expect_identical(nth(x, 4, default = \"x\"), \"x\")\n})"

const rtdal001448Source0005 = `test_that("nth works with data frames and always returns a single row", {
  x <- tibble(x = 1:3, y = 4:6)

  expect_identical(nth(x, 1), tibble(x = 1L, y = 4L))
  expect_identical(nth(x, 4), tibble(x = NA_integer_, y = NA_integer_))
  expect_identical(
    nth(x, 4, default = tibble(x = 0, y = 0)),
    tibble(x = 0L, y = 0L)
  )
})`

const rtdal001448Source0006 = `test_that("nth works with rcrds", {
  x <- new_rcrd(list(x = 1:3, y = 4:6))

  expect_identical(nth(x, 1), vec_slice(x, 1))
  expect_identical(nth(x, 4), vec_init(x))
  expect_identical(nth(x, 4, default = x[2]), x[2])
})`

const rtdal001448Source0007 = "test_that(\"drops names, because it uses `vec_slice2()`\", {\n  x <- c(a = 1, b = 2)\n  expect_named(nth(x, 2), NULL)\n})"

const rtdal001448Source0008 = `test_that("negative values index from end", {
  x <- 1:5

  expect_equal(nth(x, -1), 5L)
  expect_equal(nth(x, -3), 3L)
})`

const rtdal001448Source0009 = `test_that("indexing past ends returns default value", {
  expect_equal(nth(1:4, 5), NA_integer_)
  expect_equal(nth(1:4, -5), NA_integer_)
  expect_equal(nth(1:4, -10), NA_integer_)
  expect_equal(nth(1:4, -10, default = 6L), 6L)
})`

const rtdal001448Source0010 = `test_that("gets corner case indexing correct", {
  expect_identical(nth(1:4, -5), NA_integer_)
  expect_identical(nth(1:4, -4), 1L)
  expect_identical(nth(1:4, -3), 2L)

  expect_identical(nth(1:4, -1), 4L)
  expect_identical(nth(1:4, 0), NA_integer_)
  expect_identical(nth(1:4, 1), 1L)

  expect_identical(nth(1:4, 3), 3L)
  expect_identical(nth(1:4, 4), 4L)
  expect_identical(nth(1:4, 5), NA_integer_)
})`

