const rtdal001449Source0001 = `test_that("order_by() gives useful error messages", {
  expect_snapshot({
    (expect_error(order_by(mtcars, 10)))
    (expect_error(order_by(mtcars, cyl)))
  })
})`

const rtdal001449Source0002 = "test_that(\"`with_order()` works with data frame `order_by` (#6334)\", {\n  x <- 1:3\n  order_by <- tibble(a = c(1, 1, 2), b = c(2, 1, 1))\n\n  expect_identical(with_order(order_by, lag, x), c(2L, NA, 1L))\n})"

const rtdal001449Source0003 = "test_that(\"`with_order()` requires `order_by` and `x` to be the same size\", {\n  expect_snapshot(error = TRUE, {\n    with_order(1:2, identity, 1:3)\n  })\n})"

const rtdal001449Source0004 = `test_that("order_by() returns correct value", {
  expected <- int(15, 14, 12, 9, 5)
  expect_identical(order_by(5:1, cumsum(1:5)), expected)

  x <- 5:1
  y <- 1:5
  expect_identical(order_by(x, cumsum(y)), expected)
})`

const rtdal001449Source0005 = `test_that("order_by() works in arbitrary envs (#2297)", {
  env <- child_env("base")
  expect_equal(
    with_env(env, dplyr::order_by(5:1, cumsum(1:5))),
    rev(cumsum(rev(1:5)))
  )
  expect_equal(
    order_by(5:1, cumsum(1:5)),
    rev(cumsum(rev(1:5)))
  )
})`

const rtdal001449Source0006 = `test_that("order_by() give meaningful errors", {
  expect_snapshot({
    (expect_error(order_by(NULL, 1L)))
  })
})`

