const rtdal001455Source0001 = "test_that(\"`reframe()` allows summaries\", {\n  df <- tibble(g = c(1, 1, 1, 2, 2), x = 1:5)\n\n  expect_identical(\n    reframe(df, x = mean(x)),\n    tibble(x = 3)\n  )\n  expect_identical(\n    reframe(df, x = mean(x), .by = g),\n    tibble(g = c(1, 2), x = c(2, 4.5))\n  )\n})"

const rtdal001455Source0002 = "test_that(\"`reframe()` allows size 0 results\", {\n  df <- tibble(g = c(1, 1, 1, 2, 2), x = 1:5)\n  gdf <- group_by(df, g)\n\n  expect_identical(\n    reframe(df, x = which(x > 5)),\n    tibble(x = integer())\n  )\n  expect_identical(\n    reframe(df, x = which(x > 5), .by = g),\n    tibble(g = double(), x = integer())\n  )\n  expect_identical(\n    reframe(gdf, x = which(x > 5)),\n    tibble(g = double(), x = integer())\n  )\n})"

const rtdal001455Source0003 = "test_that(\"`reframe()` allows size >1 results\", {\n  df <- tibble(g = c(1, 1, 1, 2, 2), x = 1:5)\n  gdf <- group_by(df, g)\n\n  expect_identical(\n    reframe(df, x = which(x > 2)),\n    tibble(x = 3:5)\n  )\n  expect_identical(\n    reframe(df, x = which(x > 2), .by = g),\n    tibble(g = c(1, 2, 2), x = c(3L, 1L, 2L))\n  )\n  expect_identical(\n    reframe(gdf, x = which(x > 2)),\n    tibble(g = c(1, 2, 2), x = c(3L, 1L, 2L))\n  )\n})"

const rtdal001455Source0004 = "test_that(\"`reframe()` recycles across columns\", {\n  df <- tibble(g = c(1, 1, 2, 2, 2), x = 1:5)\n\n  out <- reframe(df, a = 1:2, b = 1L, c = 2:3)\n  expect_identical(out$a, 1:2)\n  expect_identical(out$b, c(1L, 1L))\n  expect_identical(out$c, 2:3)\n\n  out <- reframe(df, a = 1:2, b = 1L, c = 2:3, .by = g)\n  expect_identical(out$g, c(1, 1, 2, 2))\n  expect_identical(out$a, c(1:2, 1:2))\n  expect_identical(out$b, c(1L, 1L, 1L, 1L))\n  expect_identical(out$c, c(2:3, 2:3))\n})"

const rtdal001455Source0005 = "test_that(\"`reframe()` can recycle across columns to size 0\", {\n  df <- tibble(g = 1:2, x = 1:2)\n  gdf <- group_by(df, g)\n\n  out <- reframe(df, y = mean(x), z = which(x > 3))\n  expect_identical(out$y, double())\n  expect_identical(out$z, integer())\n\n  out <- reframe(df, y = mean(x), z = which(x > 1), .by = g)\n  expect_identical(out$g, 2L)\n  expect_identical(out$y, 2)\n  expect_identical(out$z, 1L)\n\n  out <- reframe(gdf, y = mean(x), z = which(x > 1))\n  expect_identical(out$g, 2L)\n  expect_identical(out$y, 2)\n  expect_identical(out$z, 1L)\n})"

const rtdal001455Source0006 = "test_that(\"`reframe()` throws intelligent recycling errors\", {\n  df <- tibble(g = 1:2, x = 1:2)\n  gdf <- group_by(df, g)\n\n  expect_snapshot(error = TRUE, {\n    reframe(df, x = 1:2, y = 3:5)\n  })\n  expect_snapshot(error = TRUE, {\n    reframe(df, x = 1:2, y = 3:5, .by = g)\n  })\n  expect_snapshot(error = TRUE, {\n    reframe(gdf, x = 1:2, y = 3:5)\n  })\n})"

const rtdal001455Source0007 = "test_that(\"`reframe()` and `summarise()` are consistent with zero expressions\", {\n  df <- tibble(x = c(\"a\", \"a\", \"b\"), y = 1:3)\n  gdf <- group_by(df, x)\n\n  expect_identical(reframe(df), tibble(.rows = 1L))\n  expect_identical(reframe(df), summarise(df))\n\n  expect_identical(reframe(df, .by = x), tibble(x = c(\"a\", \"b\")))\n  expect_identical(reframe(df, .by = x), summarise(df, .by = x))\n\n  expect_identical(reframe(gdf), tibble(x = c(\"a\", \"b\")))\n  expect_identical(reframe(gdf), summarise(gdf))\n})"

const rtdal001455Source0008 = "test_that(\"`reframe()` and `summarise()` are consistent with zero expressions and zero rows\", {\n  # The grouped cases here are special. There are \"zero groups\" to evaluate on,\n  # but we still always evaluate 1 time, and then effectively recycle the\n  # results to size 0.\n  df <- tibble(x = character(), y = integer())\n  gdf <- group_by(df, x)\n\n  expect_identical(reframe(df), tibble(.rows = 1L))\n  expect_identical(reframe(df), summarise(df))\n\n  expect_identical(reframe(df, .by = x), tibble(x = character()))\n  expect_identical(reframe(df, .by = x), summarise(df, .by = x))\n\n  expect_identical(reframe(gdf), tibble(x = character()))\n  expect_identical(reframe(gdf), summarise(gdf))\n})"

const rtdal001455Source0009 = "test_that(\"`reframe()` and `summarise()` are consistent with data frame that flattens into zero expressions\", {\n  df <- tibble(x = c(\"a\", \"a\", \"b\"), y = 1:3)\n  gdf <- group_by(df, x)\n\n  expect_identical(\n    reframe(df, tibble(.rows = 1L)),\n    tibble(.rows = 1L)\n  )\n  expect_identical(\n    reframe(df, tibble(.rows = 1L)),\n    summarise(df, tibble(.rows = 1L))\n  )\n\n  expect_identical(\n    reframe(df, tibble(.rows = 1L), .by = x),\n    tibble(x = c(\"a\", \"b\"))\n  )\n  expect_identical(\n    reframe(df, tibble(.rows = 1L), .by = x),\n    summarise(df, tibble(.rows = 1L), .by = x)\n  )\n\n  expect_identical(\n    reframe(gdf, tibble(.rows = 1L)),\n    tibble(x = c(\"a\", \"b\"))\n  )\n  expect_identical(\n    reframe(gdf, tibble(.rows = 1L)),\n    summarise(gdf, tibble(.rows = 1L))\n  )\n})"

const rtdal001455Source0010 = "test_that(\"`reframe()` and `summarise()` are consistent with data frame that flattens into zero expressions and zero rows\", {\n  # The grouped cases here are special. There are \"zero groups\" to evaluate on,\n  # but we still always evaluate 1 time, and then effectively recycle the\n  # results to size 0.\n  df <- tibble(x = character(), y = integer())\n  gdf <- group_by(df, x)\n\n  expect_identical(\n    reframe(df, tibble(.rows = 1L)),\n    tibble(.rows = 1L)\n  )\n  expect_identical(\n    reframe(df, tibble(.rows = 1L)),\n    summarise(df, tibble(.rows = 1L))\n  )\n\n  expect_identical(\n    reframe(df, tibble(.rows = 1L), .by = x),\n    tibble(x = character())\n  )\n  expect_identical(\n    reframe(df, tibble(.rows = 1L), .by = x),\n    summarise(df, tibble(.rows = 1L), .by = x)\n  )\n\n  expect_identical(\n    reframe(gdf, tibble(.rows = 1L)),\n    tibble(x = character())\n  )\n  expect_identical(\n    reframe(gdf, tibble(.rows = 1L)),\n    summarise(gdf, tibble(.rows = 1L))\n  )\n})"

const rtdal001455Source0011 = "test_that(\"`reframe()` can return more rows than the original data frame\", {\n  df <- tibble(x = 1:2)\n\n  expect_identical(\n    reframe(df, x = vec_rep_each(x, x)),\n    tibble(x = c(1L, 2L, 2L))\n  )\n})"

const rtdal001455Source0012 = "test_that(\"`reframe()` doesn't message about regrouping when multiple group columns are supplied\", {\n  df <- tibble(a = c(1, 1, 2, 2, 2), b = c(1, 2, 1, 1, 2), x = 1:5)\n  gdf <- group_by(df, a, b)\n\n  # Silence\n  expect_snapshot({\n    out <- reframe(df, x = mean(x), .by = c(a, b))\n  })\n  expect_snapshot({\n    out <- reframe(gdf, x = mean(x))\n  })\n})"

const rtdal001455Source0013 = "test_that(\"`reframe()` doesn't message about regrouping when >1 rows are returned per group\", {\n  df <- tibble(g = c(1, 1, 2, 2, 2), x = 1:5)\n  gdf <- group_by(df, g)\n\n  # Silence\n  expect_snapshot({\n    out <- reframe(df, x = vec_rep_each(x, x), .by = g)\n  })\n  expect_snapshot({\n    out <- reframe(gdf, x = vec_rep_each(x, x))\n  })\n})"

const rtdal001455Source0014 = "test_that(\"`reframe()` allows sequential assignments\", {\n  df <- tibble(g = 1:2, x = 1:2)\n\n  expect_identical(\n    reframe(df, y = 3, z = mean(x) + y),\n    tibble(y = 3, z = 4.5)\n  )\n  expect_identical(\n    reframe(df, y = 3, z = mean(x) + y, .by = g),\n    tibble(g = 1:2, y = c(3, 3), z = c(4, 5))\n  )\n})"

const rtdal001455Source0015 = "test_that(\"`reframe()` allows for overwriting existing columns\", {\n  df <- tibble(g = c(\"a\", \"b\"), x = 1:2)\n\n  expect_identical(\n    reframe(df, x = 3, z = x),\n    tibble(x = 3, z = 3)\n  )\n  expect_identical(\n    reframe(df, x = cur_group_id(), z = x, .by = g),\n    tibble(g = c(\"a\", \"b\"), x = 1:2, z = 1:2)\n  )\n})"

const rtdal001455Source0016 = "test_that(\"`reframe()` works with unquoted values\", {\n  df <- tibble(x = 1:5)\n  expect_equal(reframe(df, out = !!1), tibble(out = 1))\n  expect_equal(reframe(df, out = !!quo(1)), tibble(out = 1))\n  expect_equal(reframe(df, out = !!(1:2)), tibble(out = 1:2))\n})"

const rtdal001455Source0017 = "test_that(\"`reframe()` with bare data frames always returns a bare data frame\", {\n  df <- data.frame(g = c(1, 1, 2, 1, 2), x = c(5, 2, 1, 2, 3))\n\n  out <- reframe(df, x = mean(x))\n  expect_s3_class(out, class(df), exact = TRUE)\n\n  out <- reframe(df, x = mean(x), .by = g)\n  expect_s3_class(out, class(df), exact = TRUE)\n})"

const rtdal001455Source0018 = "test_that(\"`reframe()` drops data frame attributes\", {\n  # Because `reframe()` theoretically creates a \"new\" data frame\n\n  # With data.frames\n  df <- data.frame(g = c(1, 1, 2), x = c(1, 2, 1))\n  attr(df, \"foo\") <- \"bar\"\n\n  out <- reframe(df, x = mean(x))\n  expect_null(attr(out, \"foo\"))\n\n  out <- reframe(df, x = mean(x), .by = g)\n  expect_null(attr(out, \"foo\"))\n\n  # With tibbles\n  tbl <- as_tibble(df)\n  attr(tbl, \"foo\") <- \"bar\"\n\n  out <- reframe(tbl, x = mean(x))\n  expect_null(attr(out, \"foo\"))\n\n  out <- reframe(tbl, x = mean(x), .by = g)\n  expect_null(attr(out, \"foo\"))\n\n  # With grouped_df\n  gdf <- group_by(df, g)\n  attr(gdf, \"foo\") <- \"bar\"\n\n  out <- reframe(gdf, x = mean(x))\n  expect_null(attr(out, \"foo\"))\n})"

const rtdal001455Source0019 = "test_that(\"`reframe()` with `group_by()` sorts keys\", {\n  df <- tibble(g = c(2, 1, 2, 0), x = c(4, 2, 8, 5))\n  df <- group_by(df, g)\n\n  out <- reframe(df, x = mean(x))\n\n  expect_identical(out$g, c(0, 1, 2))\n  expect_identical(out$x, c(5, 2, 6))\n})"

const rtdal001455Source0020 = "test_that(\"`reframe()` with `group_by()` respects `.drop = FALSE`\", {\n  g <- factor(c(\"c\", \"a\", \"c\"), levels = c(\"a\", \"b\", \"c\"))\n\n  df <- tibble(g = g, x = c(1, 4, 2))\n  gdf <- group_by(df, g, .drop = FALSE)\n\n  out <- reframe(gdf, x = mean(x))\n\n  expect_identical(out$g, factor(c(\"a\", \"b\", \"c\")))\n  expect_identical(out$x, c(4, NaN, 1.5))\n})"

const rtdal001455Source0021 = "test_that(\"`reframe()` with `group_by()` always returns an ungrouped tibble\", {\n  df <- tibble(a = c(1, 1, 2, 2, 2), b = c(1, 2, 1, 1, 2), x = 1:5)\n  gdf <- group_by(df, a, b)\n\n  out <- reframe(gdf, x = mean(x))\n  expect_identical(class(out), class(df))\n})"

const rtdal001455Source0022 = "test_that(\"`reframe()` with `rowwise()` respects list-col element access\", {\n  df <- tibble(x = list(1:2, 3:5, 6L))\n  rdf <- rowwise(df)\n\n  expect_identical(\n    reframe(rdf, x),\n    tibble(x = 1:6)\n  )\n})"

const rtdal001455Source0023 = "test_that(\"`reframe()` with `rowwise()` respects rowwise group columns\", {\n  df <- tibble(g = c(1, 1, 2), x = list(1:2, 3:5, 6L))\n  rdf <- rowwise(df, g)\n\n  out <- reframe(rdf, x)\n  expect_identical(out$g, c(rep(1, 5), 2))\n  expect_identical(out$x, 1:6)\n})"

const rtdal001455Source0024 = "test_that(\"`reframe()` with `rowwise()` always returns an ungrouped tibble\", {\n  df <- tibble(g = c(1, 1, 2), x = list(1:2, 3:5, 6L))\n  rdf <- rowwise(df, g)\n\n  expect_s3_class(reframe(rdf, x), class(df), exact = TRUE)\n})"

const rtdal001455Source0025 = `test_that("named data frame results with 0 columns participate in recycling (#6509)", {
  df <- tibble(x = 1:3)
  gdf <- group_by(df, x)

  empty <- tibble()
  expect_identical(reframe(df, empty = empty), tibble(empty = empty))
  expect_identical(
    reframe(df, x = sum(x), empty = empty),
    tibble(x = integer(), empty = empty)
  )
  expect_identical(
    reframe(df, empty = empty, x = sum(x)),
    tibble(empty = empty, x = integer())
  )

  empty3 <- new_tibble(list(), nrow = 3L)
  expect_identical(reframe(df, empty = empty3), tibble(empty = empty3))
  expect_identical(
    reframe(df, x = sum(x), empty = empty3),
    tibble(x = c(6L, 6L, 6L), empty = empty3)
  )
  expect_identical(
    reframe(df, empty = empty3, x = sum(x)),
    tibble(empty = empty3, x = c(6L, 6L, 6L))
  )
})`

const rtdal001455Source0026 = "test_that(\"can group transiently using `.by`\", {\n  df <- tibble(g = c(1, 1, 2, 1, 2), x = c(5, 2, 1, 2, 3))\n\n  out <- reframe(df, x = mean(x), .by = g)\n\n  expect_identical(out$g, c(1, 2))\n  expect_identical(out$x, c(3, 2))\n  expect_s3_class(out, class(df), exact = TRUE)\n})"

const rtdal001455Source0027 = `test_that("transient grouping orders by first appearance", {
  df <- tibble(g = c(2, 1, 2, 0), x = c(4, 2, 8, 5))

  out <- reframe(df, x = mean(x), .by = g)

  expect_identical(out$g, c(2, 1, 0))
  expect_identical(out$x, c(6, 2, 5))
})`

const rtdal001455Source0028 = "test_that(\"catches `.by` with grouped-df\", {\n  df <- tibble(x = 1)\n  gdf <- group_by(df, x)\n\n  expect_snapshot(error = TRUE, {\n    reframe(gdf, .by = x)\n  })\n})"

