const rtdal001458Source0001 = `test_that("rows_insert() works", {
  data <- tibble(a = 1:3, b = letters[c(1:2, NA)], c = 0.5 + 0:2)

  expect_identical(
    rows_insert(data, tibble(a = 4L, b = "z"), by = "a"),
    tibble(a = 1:4, b = c("a", "b", NA, "z"), c = c(0.5, 1.5, 2.5, NA))
  )
})`

const rtdal001458Source0002 = `test_that("rows_insert() doesn't allow insertion of matched keys by default", {
  x <- tibble(a = 1, b = 2)

  y <- tibble(a = 1, b = 3)

  expect_snapshot(
    (expect_error(rows_insert(x, y, by = "a")))
  )

  y <- tibble(a = c(1, 1, 1), b = c(3, 4, 5))

  expect_snapshot(
    (expect_error(rows_insert(x, y, by = "a")))
  )
})`

const rtdal001458Source0003 = "test_that(\"rows_insert() allows you to ignore matched keys with `conflict = 'ignore'`\", {\n  x <- tibble(a = 1, b = 2)\n\n  y <- tibble(a = 1, b = 3)\n\n  expect_identical(rows_insert(x, y, by = \"a\", conflict = \"ignore\"), x)\n\n  y <- tibble(a = c(1, 2, 1), b = c(3, 4, 5))\n\n  expect_identical(\n    rows_insert(x, y, by = \"a\", conflict = \"ignore\"),\n    rows_insert(x, y[2, ], by = \"a\")\n  )\n})"

