const rtdal001458Source0005 = "test_that(\"rows_insert() allows `y` keys to be duplicated (#5553)\", {\n  x <- tibble(a = 2, b = 4)\n  y <- tibble(a = c(1, 1), b = c(2, 3))\n\n  expect_identical(\n    rows_insert(x, y, by = \"a\"),\n    tibble(a = c(2, 1, 1), b = c(4, 2, 3))\n  )\n})"

