const rtdal001458Source0008 = "test_that(\"rows_insert() checks that `x` and `y` contain `by` (#6652)\", {\n  x <- tibble(a = 1, b = 2)\n  y <- tibble(a = 1)\n\n  expect_snapshot({\n    (expect_error(rows_insert(x, y, by = \"c\")))\n  })\n  expect_snapshot({\n    (expect_error(rows_insert(x, y, by = c(\"a\", \"b\"))))\n  })\n})"

