const rtdal001458Source0049 = "test_that(\"rows_check_contains_by() checks that all `by` columns are in `x`\", {\n  x <- tibble(x = 1)\n\n  expect_snapshot({\n    (expect_error(rows_check_contains_by(x, \"y\", arg = \"x\")))\n    (expect_error(rows_check_contains_by(x, c(\"y\", \"x\", \"z\"), arg = \"y\")))\n  })\n})"

const rtdal001458Source0050 = `test_that("rows_check_unique() requires uniqueness", {
  x <- tibble(x = c(1, 1, 1), y = c(2, 3, 2), z = c(1, 2, 3))

  expect_silent(rows_check_unique(x, "x"))

  expect_snapshot({
    (expect_error(rows_check_unique(x["x"], "x")))
    (expect_error(rows_check_unique(x[c("x", "y")], "y")))
  })
})`

