const rtdal001459Source0001 = `test_that("rowwise status preserved by major verbs", {
  rf <- rowwise(tibble(x = 1:5, y = 5:1), "x")

  out <- arrange(rf, y)
  expect_s3_class(out, "rowwise_df")
  expect_equal(group_vars(out), "x")

  out <- filter(rf, x < 3)
  expect_s3_class(out, "rowwise_df")
  expect_equal(group_vars(out), "x")

  out <- filter_out(rf, x < 3)
  expect_s3_class(out, "rowwise_df")
  expect_equal(group_vars(out), "x")

  out <- mutate(rf, x = x + 1)
  expect_s3_class(out, "rowwise_df")
  expect_equal(group_vars(out), "x")

  out <- rename(rf, X = x)
  expect_s3_class(out, "rowwise_df")
  expect_equal(group_vars(out), "X")

  out <- select(rf, "x")
  expect_s3_class(out, "rowwise_df")
  expect_equal(group_vars(out), "x")

  out <- slice(rf, c(1, 1))
  expect_s3_class(out, "rowwise_df")
  expect_equal(group_vars(out), "x")

  # Except for summarise
  out <- summarise(rf, z = mean(x, y))
  expect_s3_class(out, "grouped_df")
  expect_equal(group_vars(out), "x")
})`

const rtdal001459Source0002 = `test_that("rowwise nature preserved by subsetting ops", {
  rf <- rowwise(tibble(x = 1:5, y = 1:5), "x")

  out <- rf[1]
  expect_s3_class(out, "rowwise_df")
  expect_equal(group_vars(out), "x")

  out[, "z"] <- 5:1
  expect_s3_class(out, "rowwise_df")
  expect_equal(group_vars(out), "x")

  names(out) <- toupper(names(out))
  expect_s3_class(out, "rowwise_df")
  expect_equal(group_vars(out), "X")
})`

const rtdal001459Source0003 = `test_that("except when it should be removed", {
  rf <- rowwise(tibble(x = 1:5, y = 1:5), "x")
  expect_equal(out <- rf[, 1, drop = TRUE], rf$x)
})`

const rtdal001459Source0004 = `test_that("rowwise has decent print method", {
  rf <- rowwise(tibble(x = 1:5), "x")
  expect_snapshot(rf)
})`

const rtdal001459Source0005 = `test_that("rowwise captures group_vars", {
  df <- group_by(tibble(g = 1:2, x = 1:2), g)
  rw <- rowwise(df)
  expect_equal(group_vars(rw), "g")

  # but can't regroup
  expect_error(rowwise(df, x), "Can't re-group")
})`

const rtdal001459Source0006 = `test_that("can re-rowwise", {
  rf1 <- rowwise(tibble(x = 1:5, y = 1:5), "x")
  rf2 <- rowwise(rf1, y)
  expect_equal(group_vars(rf2), "y")
})`

const rtdal001459Source0007 = "test_that(\"new_rowwise_df() does not require `group_data=`\", {\n  df <- new_rowwise_df(data.frame(x = 1:2))\n  expect_s3_class(df, \"rowwise_df\")\n  expect_equal(attr(df, \"groups\"), tibble(\".rows\" := vctrs::list_of(1L, 2L)))\n})"

const rtdal001459Source0008 = `test_that("new_rowwise_df() can add class and attributes (#5918)", {
  df <- new_rowwise_df(
    tibble(x = 1:4),
    tibble(),
    class = "custom_rowwise_df",
    a = "b"
  )
  expect_s3_class(df, "custom_rowwise_df")
  expect_equal(attr(df, "a"), "b")
})`

const rtdal001459Source0009 = "test_that(\"rbind() works with rowwise data frames by calling bind_rows() (r-lib/vctrs#1935)\", {\n  x <- rowwise(tibble(a = 1:2))\n\n  y <- rowwise(tibble(a = 3:4))\n  out <- rbind(x, y)\n  expect_identical(out, rowwise(tibble(a = c(1:2, 3:4))))\n\n  # Important that `.rows` is recreated, not copied over from `x` (r-lib/vctrs#1935)\n  expect_identical(\n    group_data(out),\n    new_tibble(list(.rows = list_of(1L, 2L, 3L, 4L)))\n  )\n\n  # `bind_rows()` returns an object with the class of the first input,\n  # which is roughly how `rbind()` also works\n\n  # With bare tibble\n  y <- tibble(a = 5:6)\n  out <- rbind(x, y)\n  expect_identical(out, rowwise(tibble(a = c(1:2, 5:6))))\n\n  # With grouped_df\n  y <- group_by(tibble(a = 5:6), a)\n  out <- rbind(x, y)\n  expect_identical(out, rowwise(tibble(a = c(1:2, 5:6))))\n})"

const rtdal001459Source0010 = `test_that("validate_rowwise_df() gives useful errors", {
  df1 <- rowwise(tibble(x = 1:4, g = rep(1:2, each = 2)), g)
  groups <- attr(df1, "groups")
  groups[[2]] <- 4:1
  attr(df1, "groups") <- groups

  df2 <- rowwise(tibble(x = 1:4, g = rep(1:2, each = 2)), g)
  groups <- attr(df2, "groups")
  names(groups) <- c("g", "not.rows")
  attr(df2, "groups") <- groups

  df3 <- df2
  attr(df3, "groups") <- tibble()

  df4 <- df3
  attr(df4, "groups") <- NA

  df7 <- rowwise(tibble(x = 1:10))
  attr(df7, "groups")$.rows <- 11:20

  df8 <- rowwise(tibble(x = 1:10))

  df10 <- df7
  attr(df10, "groups") <- tibble()

  df11 <- df7
  attr(df11, "groups") <- NULL

  expect_snapshot({
    (expect_error(validate_rowwise_df(df1)))
    (expect_error(validate_rowwise_df(df2)))
    (expect_error(validate_rowwise_df(df3)))
    (expect_error(validate_rowwise_df(df4)))
    (expect_error(validate_rowwise_df(df7)))
    (expect_error(attr(df8, "groups")$.rows <- 1:8))
    (expect_error(validate_rowwise_df(df10)))
    (expect_error(validate_rowwise_df(df11)))

    (expect_error(
      new_rowwise_df(
        tibble(x = 1:10),
        tibble(".rows" := list(1:5, -1L))
      )
    ))

    (expect_error(
      new_rowwise_df(
        tibble(x = 1:10),
        1:10
      )
    ))
  })
})`

