const rtdal001462Source0001 = `test_that("select preserves grouping", {
  gf <- group_by(tibble(g = 1:3, x = 3:1), g)

  i <- count_regroups(out <- select(gf, h = g))
  expect_equal(i, 0)
  expect_equal(group_vars(out), "h")
})`

const rtdal001462Source0002 = `test_that("grouping variables preserved with a message, unless already selected (#1511, #5841)", {
  df <- tibble(g = 1:3, x = 3:1) |> group_by(g)

  expect_snapshot({
    res <- select(df, x)
  })
  expect_named(res, c("g", "x"))

  df <- tibble(a = 1, b = 2, c = 3) |> group_by(a)
  expect_equal(df |> select(a = b), tibble(a = 2))

  df <- tibble(a = 1, b = 2, c = 3) |> group_by(a, b)
  expect_snapshot({
    expect_equal(df |> select(a = c), tibble(b = 2, a = 3) |> group_by(b))
    expect_equal(df |> select(b = c), tibble(a = 1, b = 3) |> group_by(a))
  })
})`

const rtdal001462Source0003 = "test_that(\"non-syntactic grouping variable is preserved (#1138)\", {\n  expect_snapshot(\n    df <- tibble(`a b` = 1L) |> group_by(`a b`) |> select()\n  )\n  expect_named(df, \"a b\")\n})"

const rtdal001462Source0004 = `test_that("select doesn't fail if some names missing", {
  df1 <- data.frame(x = 1:10, y = 1:10, z = 1:10)
  df2 <- setNames(df1, c("x", "y", ""))
  # df3 <- setNames(df1, c("x", "", ""))

  expect_equal(select(df1, x), data.frame(x = 1:10))
  expect_equal(select(df2, x), data.frame(x = 1:10))
  # expect_equal(select(df3, x), data.frame(x = 1:10))
})`

const rtdal001462Source0005 = `test_that("select with no args returns nothing", {
  empty <- select(mtcars)
  expect_equal(df_n_col(empty), 0)
  expect_equal(nrow(empty), 32)

  empty <- select(mtcars, !!!list())
  expect_equal(df_n_col(empty), 0)
  expect_equal(nrow(empty), 32)
})`

const rtdal001462Source0006 = `test_that("select excluding all vars returns nothing", {
  expect_equal(dim(select(mtcars, -(mpg:carb))), c(32, 0))
  expect_equal(dim(select(mtcars, starts_with("x"))), c(32, 0))
  expect_equal(dim(select(mtcars, -matches("."))), c(32, 0))
})`

const rtdal001462Source0007 = `test_that("negating empty match returns everything", {
  df <- data.frame(x = 1:3, y = 3:1)
  expect_equal(select(df, -starts_with("xyz")), df)
})`

const rtdal001462Source0008 = `test_that("can select with duplicate columns", {
  df <- tibble(x = 1, x = 2, y = 1, .name_repair = "minimal")

  # can extract duplicate cols by position
  expect_named(df |> select(1, 3), c("x", "y"))

  # can select out non-duplicated columns
  expect_named(df |> select(y), "y")
})`

const rtdal001462Source0009 = `test_that("select can be before group_by (#309)", {
  df <- data.frame(
    id = c(1, 1, 2, 2, 2, 3, 3, 4, 4, 5),
    year = c(2013, 2013, 2012, 2013, 2013, 2013, 2012, 2012, 2013, 2013),
    var1 = rnorm(10)
  )
  dfagg <- df |>
    group_by(id, year) |>
    select(id, year, var1) |>
    summarise(var1 = mean(var1))
  expect_equal(names(dfagg), c("id", "year", "var1"))
})`

const rtdal001462Source0010 = `test_that("select succeeds in presence of raw columns (#1803)", {
  df <- tibble(a = 1:3, b = as.raw(1:3))
  expect_identical(select(df, a), df["a"])
  expect_identical(select(df, b), df["b"])
  expect_identical(select(df, -b), df["a"])
})`

const rtdal001462Source0011 = `test_that("arguments to select() don't match vars_select() arguments", {
  df <- tibble(a = 1)
  expect_identical(select(df, var = a), tibble(var = 1))
  expect_identical(
    select(group_by(df, a), var = a),
    group_by(tibble(var = 1), var)
  )
  expect_identical(select(df, exclude = a), tibble(exclude = 1))
  expect_identical(select(df, include = a), tibble(include = 1))
  expect_identical(
    select(group_by(df, a), exclude = a),
    group_by(tibble(exclude = 1), exclude)
  )
  expect_identical(
    select(group_by(df, a), include = a),
    group_by(tibble(include = 1), include)
  )
})`

const rtdal001462Source0012 = "test_that(\"can select() with deprecated `.data` pronoun (#2715)\", {\n  withr::local_options(lifecycle_verbosity = \"quiet\")\n  expect_identical(select(mtcars, .data$cyl), select(mtcars, cyl))\n})"

const rtdal001462Source0013 = `test_that("can select() with character vectors", {
  expect_identical(
    select(mtcars, "cyl", !!"disp", c("cyl", "am", "drat")),
    mtcars[c("cyl", "disp", "am", "drat")]
  )
})`

const rtdal001462Source0014 = `test_that("select() treats NULL inputs as empty", {
  expect_identical(select(mtcars, cyl), select(mtcars, NULL, cyl, NULL))
})`

const rtdal001462Source0015 = `test_that("can select() with strings and character vectors", {
  vars <- c(foo = "cyl", bar = "am")

  expect_identical(select(mtcars, !!!vars), select(mtcars, foo = cyl, bar = am))
  expect_identical(select(mtcars, !!vars), select(mtcars, foo = cyl, bar = am))
})`

const rtdal001462Source0016 = `test_that("select works on empty names (#3601)", {
  df <- data.frame(x = 1, y = 2, z = 3)
  colnames(df) <- c("x", "y", "")
  expect_identical(select(df, x)$x, 1)

  colnames(df) <- c("", "y", "z")
  expect_identical(select(df, y)$y, 2)
})`

const rtdal001462Source0017 = `test_that("select works on NA names (#3601)", {
  df <- data.frame(x = 1, y = 2, z = 3)
  colnames(df) <- c("x", "y", NA)
  expect_identical(select(df, x)$x, 1)

  colnames(df) <- c(NA, "y", "z")
  expect_identical(select(df, y)$y, 2)
})`

const rtdal001462Source0018 = `test_that("select() keeps attributes of raw data frames (#5831)", {
  df <- data.frame(x = 1)
  attr(df, "a") <- "b"
  expect_equal(attr(select(df, x), "a"), "b")
})`

const rtdal001462Source0019 = `test_that("select() provides informative errors", {
  expect_snapshot({
    (expect_error(select(mtcars, 1 + "")))
  })
})`

const rtdal001462Source0020 = "test_that(\"dplyr_col_select() aborts when `[` implementation is broken\", {\n  local_methods(\n    \"[.dplyr_test_broken_operator\" = function(x, ...) {\n      unclass(x)\n    },\n    \"[.dplyr_test_operator_wrong_size\" = function(x, ...) {\n      data.frame()\n    }\n  )\n  df1 <- new_tibble(\n    list(x = 1),\n    nrow = 1L,\n    class = \"dplyr_test_broken_operator\"\n  )\n  expect_snapshot({\n    (expect_error(\n      select(df1, 1:2)\n    ))\n    (expect_error(\n      select(df1, 0)\n    ))\n  })\n  df2 <- new_tibble(\n    list(x = 1),\n    nrow = 1L,\n    class = \"dplyr_test_operator_wrong_size\"\n  )\n  expect_error(select(df2, 1:2))\n\n  expect_snapshot({\n    # from vctrs\n    (expect_error(\n      select(df1, 2)\n    ))\n\n    # not returning a data frame\n    (expect_error(\n      select(df1, 1)\n    ))\n\n    # unexpected number of columns\n    (expect_error(\n      select(df2, 1)\n    ))\n  })\n})"

