const rtdal001466Source0036 = "test_that(\"summarise() messages about implicit `.groups` default\", {\n  # Otherwise it only informs when called from the global env\n  local_options(dplyr.summarise.inform = TRUE)\n\n  df <- tibble(x = 1, y = 2)\n\n  # Nothing\n  expect_snapshot({\n    df |> group_by(x) |> summarise()\n  })\n  expect_snapshot({\n    df |> rowwise() |> summarise()\n  })\n\n  # Implicit `\"drop_last\"`\n  expect_snapshot({\n    df |> group_by(x, y) |> summarise()\n  })\n\n  # Implicit `\"keep\"`\n  expect_snapshot({\n    df |> rowwise(x, y) |> summarise()\n  })\n})"

const rtdal001466Source0037 = "test_that(\"summarise() respects `dplyr.summarise.inform = FALSE`\", {\n  local_options(dplyr.summarise.inform = FALSE)\n\n  # Force evaluation in the global env so we can be very sure we are\n  # silencing the message. It only ever triggers in the global env.\n  eval_global <- function(expr) eval(expr, envir = globalenv())\n\n  # Implicit `\"drop_last\"`\n  expect_snapshot({\n    eval_global(tibble(x = 1, y = 2) |> group_by(x, y) |> summarise())\n  })\n\n  # Implicit `\"keep\"`\n  expect_snapshot({\n    eval_global(tibble(x = 1, y = 2) |> rowwise(x, y) |> summarise())\n  })\n})"

const rtdal001466Source0038 = `test_that("summarise() gives meaningful errors", {
  eval(
    envir = global_env(),
    expr({
      expect_snapshot({
        # unsupported type
        (expect_error(
          tibble(x = 1, y = c(1, 2, 2), z = runif(3)) |>
            summarise(a = rlang::env(a = 1))
        ))
        (expect_error(
          tibble(x = 1, y = c(1, 2, 2), z = runif(3)) |>
            group_by(x, y) |>
            summarise(a = rlang::env(a = 1))
        ))
        (expect_error(
          tibble(x = 1, y = c(1, 2, 2), y2 = c(1, 2, 2), z = runif(3)) |>
            group_by(x, y, y2) |>
            summarise(a = rlang::env(a = 1))
        ))
        (expect_error(
          tibble(x = 1, y = c(1, 2, 2), z = runif(3)) |>
            rowwise() |>
            summarise(a = lm(y ~ x))
        ))

        # mixed types
        (expect_error(
          tibble(id = 1:2, a = list(1, "2")) |>
            group_by(id) |>
            summarise(a = a[[1]])
        ))
        (expect_error(
          tibble(id = 1:2, a = list(1, "2")) |>
            rowwise() |>
            summarise(a = a[[1]])
        ))

        # mixed nulls
        (expect_error(
          data.frame(x = 1:2, g = 1:2) |>
            group_by(g) |>
            summarise(x = if (g == 1) 42)
        ))
        (expect_error(
          data.frame(x = 1:2, g = 1:2) |>
            group_by(g) |>
            summarise(x = if (g == 2) 42)
        ))

        # .data pronoun
        (expect_error(summarise(tibble(a = 1), c = .data$b)))
        (expect_error(summarise(group_by(tibble(a = 1:3), a), c = .data$b)))

        # Duplicate column names
        (expect_error(
          tibble(x = 1, x = 1, .name_repair = "minimal") |> summarise(x)
        ))

        # Not glue()ing
        (expect_error(tibble() |> summarise(stop("{"))))
        (expect_error(
          tibble(a = 1, b = "{value:1, unit:a}") |>
            group_by(b) |>
            summarise(a = stop("!"))
        ))
      })
    })
  )
})`

const rtdal001466Source0039 = "test_that(\"non-summary results are defunct in favor of `reframe()` (#6382, #7761)\", {\n  df <- tibble(g = c(1, 1, 2), x = 1:3)\n  gdf <- group_by(df, g)\n  rdf <- rowwise(df)\n\n  expect_snapshot(error = TRUE, {\n    out <- summarise(df, x = which(x < 3))\n  })\n  expect_snapshot(error = TRUE, {\n    out <- summarise(df, x = which(x < 3), .by = g)\n  })\n\n  # First group returns size 2 summary\n  expect_snapshot(error = TRUE, {\n    out <- summarise(gdf, x = which(x < 3))\n  })\n\n  # Last row returns size 0 summary\n  expect_snapshot(error = TRUE, {\n    out <- summarise(rdf, x = which(x < 3))\n  })\n\n  # A few additional tests from when we used to allow this, which are now errors\n  expect_snapshot(error = TRUE, {\n    tibble() |> summarise(x = 1, y = 1:3, z = 1)\n  })\n  expect_snapshot(error = TRUE, {\n    gf <- group_by(tibble(a = 1:2), a)\n    gf |> summarise(x = 1, y = 1:3, z = 1)\n  })\n  expect_snapshot(error = TRUE, {\n    gf <- group_by(tibble(a = 1:2), a)\n    gf |> summarise(x = seq_len(a), y = 1)\n  })\n})"

