const rtdal001469Source0001 = "test_that(\"non-syntactic grouping variable is preserved (#1138)\", {\n  df <- tibble(`a b` = 1L) |> group_by(`a b`) |> transmute()\n  expect_named(df, \"a b\")\n})"

const rtdal001469Source0002 = `test_that("transmute preserves grouping", {
  gf <- group_by(tibble(x = 1:2, y = 2), x)

  i <- count_regroups(out <- transmute(gf, x = 1))
  expect_equal(i, 1L)
  expect_equal(group_vars(out), "x")
  expect_equal(nrow(group_data(out)), 1)

  i <- count_regroups(out <- transmute(gf, z = 1))
  expect_equal(i, 0)
  expect_equal(group_data(out), group_data(gf))
})`

const rtdal001469Source0003 = `test_that("transmute with no args returns grouping vars", {
  df <- tibble(x = 1, y = 2)
  gf <- group_by(df, x)

  expect_equal(df |> transmute(), df[integer()])
  expect_equal(gf |> transmute(), gf[1L])
})`

const rtdal001469Source0004 = `test_that("transmute succeeds in presence of raw columns (#1803)", {
  df <- tibble(a = 1:3, b = as.raw(1:3))
  expect_identical(transmute(df, a), df["a"])
  expect_identical(transmute(df, b), df["b"])
})`

const rtdal001469Source0005 = `test_that("arguments to transmute() don't match vars_transmute() arguments", {
  df <- tibble(a = 1)
  expect_identical(transmute(df, var = a), tibble(var = 1))
  expect_identical(transmute(df, exclude = a), tibble(exclude = 1))
  expect_identical(transmute(df, include = a), tibble(include = 1))
})`

const rtdal001469Source0006 = `test_that("arguments to rename() don't match vars_rename() arguments (#2861)", {
  df <- tibble(a = 1)
  expect_identical(rename(df, var = a), tibble(var = 1))
  expect_identical(
    rename(group_by(df, a), var = a),
    group_by(tibble(var = 1), var)
  )
  expect_identical(rename(df, strict = a), tibble(strict = 1))
  expect_identical(
    rename(group_by(df, a), strict = a),
    group_by(tibble(strict = 1), strict)
  )
})`

const rtdal001469Source0007 = `test_that("can transmute() with .data pronoun (#2715)", {
  expect_identical(transmute(mtcars, .data$cyl), transmute(mtcars, cyl))
})`

const rtdal001469Source0008 = `test_that("transmute() does not warn when a variable is removed with = NULL (#4609)", {
  df <- data.frame(x = 1)
  expect_warning(transmute(df, y = x + 1, z = y * 2, y = NULL), NA)
})`

const rtdal001469Source0009 = `test_that("transmute() can handle auto splicing", {
  expect_equal(
    iris |> transmute(tibble(Sepal.Length, Sepal.Width)),
    iris |> select(Sepal.Length, Sepal.Width)
  )
})`

const rtdal001469Source0010 = "test_that(\"transmute() retains ordering supplied in `...`, even for pre-existing columns (#6086)\", {\n  df <- tibble(x = 1:3, y = 4:6)\n  out <- transmute(df, x, z = x + 1, y)\n  expect_named(out, c(\"x\", \"z\", \"y\"))\n})"

const rtdal001469Source0011 = "test_that(\"transmute() retains ordering supplied in `...`, even for group columns (#6086)\", {\n  df <- tibble(x = 1:3, g1 = 1:3, g2 = 1:3, y = 4:6)\n  df <- group_by(df, g1, g2)\n\n  out <- transmute(df, x, z = x + 1, y, g1)\n\n  # - Untouched group variables are first\n  # - Following by ordering supplied through `...`\n  expect_named(out, c(\"g2\", \"x\", \"z\", \"y\", \"g1\"))\n})"

const rtdal001469Source0012 = `test_that("transmute() error messages", {
  expect_snapshot({
    (expect_error(transmute(mtcars, cyl2 = cyl, .keep = 'all')))
    (expect_error(transmute(mtcars, cyl2 = cyl, .before = disp)))
    (expect_error(transmute(mtcars, cyl2 = cyl, .after = disp)))
  })
})`

