const rtdal001494Source0001 = `naiveBayes <- function(x, ...)
    UseMethod("naiveBayes")`

const rtdal001494Source0002 = `naiveBayes.default <- function(x, y, laplace = 0, ...) {
    call <- match.call()
    Yname <- deparse(substitute(y))
    x <- as.data.frame(x)
    if (is.logical(y))
        y <- factor(y, levels = c("FALSE", "TRUE"))
    
    ## estimation-function
    est <- function(var)
        if (is.numeric(var)) {
            cbind(tapply(var, y, mean, na.rm = TRUE),
                  tapply(var, y, sd, na.rm = TRUE))
        } else {
            if (is.logical(var))
                var <- factor(var, levels = c("FALSE", "TRUE"))
            tab <- table(y, var)
            (tab + laplace) / (rowSums(tab) + laplace * nlevels(var))
        }

    ## create tables
    apriori <- table(y)
    tables <- lapply(x, est)
    isnumeric <- vapply(x, is.numeric, NA)

    ## fix dimname names
    for (i in 1:length(tables))
        names(dimnames(tables[[i]])) <- c(Yname, colnames(x)[i])
    names(dimnames(apriori)) <- Yname

    structure(list(apriori = apriori,
                   tables = tables,
                   levels = names(apriori),
                   isnumeric = isnumeric,
                   call   = call
                   ),

              class = "naiveBayes"
              )
}`

const rtdal001494Source0003 = "naiveBayes.formula <- function(formula, data, laplace = 0, ...,\n                               subset, na.action = na.pass) {\n    call <- match.call()\n    Yname <- as.character(formula[[2]])\n\n    if (is.data.frame(data)) {\n        ## handle formula\n        m <- match.call(expand.dots = FALSE)\n        m$... <- NULL\n        m$laplace = NULL\n        m$na.action <- na.action\n        m[[1L]] <- quote(stats::model.frame)\n        m <- eval(m, parent.frame())\n        Terms <- attr(m, \"terms\")\n        if (any(attr(Terms, \"order\") > 1))\n            stop(\"naiveBayes cannot handle interaction terms\")\n        Y <- model.extract(m, \"response\")\n        X <- m[,gsub(\"`\", \"\", labels(Terms)), drop = FALSE]\n\n        return(naiveBayes(X, Y, laplace = laplace, ...))\n    } else if (is.array(data)) {\n        nam <- names(dimnames(data))\n        ## Find Class dimension\n        Yind <- which(nam == Yname)\n\n        ## Create Variable index\n#        deps <- strsplit(as.character(formula)[3], \".[+].\")[[1]]\n        deps <- labels(terms(formula, data = data))\n        if (length(deps) == 1 && deps == \".\")\n            deps <- nam[-Yind]\n        Vind <- which(nam %in% deps)\n\n        ## create tables\n        apriori <- margin.table(data, Yind)\n        tables <- lapply(Vind,\n                         function(i) (margin.table(data, c(Yind, i)) + laplace) /\n                         (as.numeric(apriori) + laplace * dim(data)[i]))\n        names(tables) <- nam[Vind]\n\n        isnumeric = rep(FALSE, length(Vind))\n        names(isnumeric) <- nam[Vind]\n\n        structure(list(apriori = apriori,\n                       tables = tables,\n                       levels = names(apriori),\n                       isnumeric = isnumeric,\n                       call   = call\n                       ),\n\n                  class = \"naiveBayes\"\n                  )\n    } else stop(\"naiveBayes formula interface handles data frames or arrays only\")\n\n}"

const rtdal001494Source0004 = `print.naiveBayes <- function(x, ...) {
    cat("\nNaive Bayes Classifier for Discrete Predictors\n\n")
    cat("Call:\n")
    print(x$call)
    cat("\nA-priori probabilities:\n")
    print(x$apriori / sum(x$apriori))

    cat("\nConditional probabilities:\n")
    for (i in x$tables) {print(i); cat("\n")}

}`

const rtdal001494Source0005 = `predict.naiveBayes <- function(object,
                               newdata,
                               type = c("class", "raw"),
                               threshold = 0.001,
                               eps = 0,
                               ...) {
    type <- match.arg(type)
    newdata <- as.data.frame(newdata)

    ## fix factor levels to be identical with training data
    for (i in names(object$tables)) {
        if (!is.null(newdata[[i]]) && !is.numeric(newdata[[i]]))
            newdata[[i]] <- factor(newdata[[i]], levels = colnames(object$tables[[i]]))
        if (object$isnumeric[i] != is.numeric(newdata[[i]]))
            warning(paste0("Type mismatch between training and new data for variable '", i,
                           "'. Did you use factors with numeric labels for training, and numeric values for new data?"))
    }

    attribs <- match(names(object$tables), names(newdata))
    isnumeric <- vapply(newdata, is.numeric, NA)
    islogical <- vapply(newdata, is.logical, NA)
    newdata <- data.matrix(newdata)
    len <- length(object$apriori)
    L <- vapply(seq_len(nrow(newdata)), function(i) {
        ndata <- newdata[i, ]
        L <- log(object$apriori) + apply(log(vapply(seq_along(attribs),
            function(v) {
                nd <- ndata[attribs[v]]
                if (is.na(nd)) rep.int(1, len) else {
                  prob <- if (isnumeric[attribs[v]]) {
                    msd <- object$tables[[v]]
                    msd[, 2][msd[, 2] <= eps] <- threshold
                    dnorm(nd, msd[, 1], msd[, 2])
                  } else object$tables[[v]][, nd + islogical[attribs[v]]]
                  prob[prob <= eps] <- threshold
                  prob
                }
            }, double(len))), 1, sum)
        if (type == "class")
            L
        else {
            ## Numerically unstable:
            ##            L <- exp(L)
            ##            L / sum(L)
            ## instead, we use:
            vapply(L, function(lp) {
                1/sum(exp(L - lp))
            }, double(1))
        }
    }, double(len))
    if (type == "class") {
        if (is.logical(object$levels))
            L[2,] > L[1,]
        else
            factor(object$levels[apply(L, 2, which.max)], levels = object$levels)
    } else t(L)
}`

